// Original AscendSAT instruction and practice. Not College Board questions.
// Framework/exam review: November 7, 2026; targets May 2027 history exam updates.
const periods = ['1491–1607','1607–1754','1754–1800','1800–1848','1844–1877','1865–1898','1890–1945','1945–1980','1980–Present'];
const domain = (unit:number) => `APUSH: ${periods[unit-1]}`;
const chapters:any[] = [];
function chapter(unit:number,number:number,title:string,explanation:string,worked:string,error:string,check:string,terms:string[][]){chapters.push({unit,number,title,explanation,worked,error,check,terms});}
chapter(1,1,'Native North America before European Colonization',
`North America in 1491 contained many societies, not one uniform culture. Different environments encouraged different combinations of farming, hunting, fishing, gathering, and trade. In the Southwest, irrigation supported settled agricultural communities; ancestral Pueblo peoples built substantial settlements, while later Pueblo communities adapted to local water supplies. On the Pacific coast, abundant marine resources sustained densely settled communities without the same dependence on maize agriculture. In the Great Plains, hunting and cultivation varied by place and period. The familiar image of mounted Plains buffalo hunters belongs largely to the era after Europeans introduced horses.

Maize cultivation spread northward over centuries and helped support population growth and political complexity. Mississippian centers such as Cahokia linked farming communities to extensive exchange networks. Cahokia's peak preceded 1491, so its remains demonstrate earlier Indigenous urbanism rather than an unchanged city encountered by English colonists. In the Northeast, Haudenosaunee communities combined agriculture with hunting and diplomacy; their confederacy illustrates political cooperation without a European-style centralized state.

These examples establish a causal relationship between environment and social organization without treating geography as destiny. People changed their environments through farming, controlled burning, settlement, and exchange. Kinship, gender roles, spiritual traditions, and local political decisions also shaped economic life. Indigenous nations maintained distinct identities while interacting with neighbors. European arrival therefore disrupted existing systems of power rather than bringing history to an empty continent.`,
`Worked comparison: Compare a Pueblo agricultural community with a Northwest Coast fishing community. Both could maintain settled populations and exchange goods, but reliable food came from different resource systems. Explain the mechanism: irrigation organized labor around scarce water, whereas rich fisheries supported harvesting and preservation. A defensible claim is that ecological opportunities encouraged different forms of cooperation, not that one community was more advanced. Cite the particular resource and resulting practice before discussing broader similarities.`,
`Do not project nineteenth-century horse culture backward into 1491, call all Indigenous people nomadic, or assume that shared land-use practices meant an absence of territorial rights. Avoid using one nation's experience to describe the entire continent.`,
`Check: Why does evidence of Cahokia challenge an account that begins American urban history with European settlement? Answer: Its precontact population, monumental construction, agriculture, and exchange demonstrate that Indigenous people created complex urban networks long before English colonization.`,
[['Maize agriculture','Cultivation of corn, spreading across the Americas over many centuries; it helped sustain population growth and settled communities but did not make all Indigenous economies identical.'],['Cahokia','A major Mississippian urban and ceremonial center near present-day St. Louis whose peak preceded 1491.'],['Haudenosaunee Confederacy','An alliance of Indigenous nations in the Northeast that coordinated diplomacy and collective political decisions while retaining member identities.'],['Environmental adaptation','The ways people adjust economic and social practices to local conditions while also reshaping those conditions through human choices.']]);
chapter(1,2,'Atlantic Expansion and the Columbian Exchange',
`European Atlantic expansion emerged from commercial competition, state building, religious goals, and changing maritime knowledge. Iberian rulers and merchants sought access to Asian trade and resources without relying solely on existing overland and Mediterranean intermediaries. Navigation techniques developed through exchanges among several cultures; expansion was not simply the result of a uniquely European invention. Columbus's 1492 voyage connected previously separated Atlantic worlds, although he misunderstood the geography of the lands he reached.

The Columbian Exchange describes transfers of organisms, crops, people, and pathogens following sustained contact. American maize and potatoes eventually supported population growth in parts of Europe, Africa, and Asia. Horses changed transportation and warfare in many Indigenous communities. European livestock could damage Indigenous fields, making biological exchange a source of conflict over land as well as a story of new foods.

Disease caused catastrophic Indigenous population losses because many American communities lacked previous exposure to pathogens such as smallpox. Epidemics interacted with warfare, forced labor, displacement, and hunger; they should not be used to erase human responsibility for conquest. Demographic collapse weakened some communities' military and political capacity, but survivors adapted, migrated, rebuilt alliances, and resisted.

The emerging Atlantic economy also intensified the forced migration of Africans. European access to land and American crops did not produce the same opportunities for all people. Some merchants and states accumulated wealth while colonized and enslaved populations bore enormous losses. Distinguish a biological transfer from the political institutions that organized extraction: neither disease nor crops alone explain the creation of colonial empires.`,
`Worked causal chain: Smallpox reaches a region, population falls, and colonizers demand labor from surviving communities. A strong explanation connects demographic losses to disrupted food production and weakened resistance, while identifying coercive labor policies as separate choices. A weak explanation says disease automatically caused European control everywhere. Compare timing and local alliances: Europeans often depended on Indigenous rivals of existing powers. Multiple interacting causes explain conquest more effectively than a single technological advantage.`,
`The Exchange was not an equal commercial bargain. Forced migration belongs in the account alongside crops. Do not say Europeans deliberately introduced every epidemic or that all Indigenous communities disappeared after contact.`,
`Check: Why can horses and smallpox both belong to the Columbian Exchange despite producing different effects? Answer: The concept concerns cross-Atlantic biological transfers; their consequences ranged from new mobility to demographic catastrophe rather than one uniformly beneficial outcome.`,
[['Columbian Exchange','Transfers of plants, animals, pathogens, and people across the Atlantic after sustained contact began in 1492.'],['Atlantic World','An interconnected zone linking Europe, Africa, and the Americas through commerce, migration, empire, and coercion.'],['Demographic collapse','A severe population decline; in the Americas epidemics interacted with conquest, displacement, forced labor, and disrupted subsistence.'],['Middle Passage','The forced Atlantic crossing of enslaved Africans, a violent part of the broader transatlantic slave trade.']]);
chapter(1,3,'Conquest, Labor, and Debates over Empire',
`Spanish colonization combined conquest with institutions designed to extract wealth and extend royal and Catholic authority. Conquistadors formed alliances with Indigenous groups whose own political goals could include defeating local enemies. Their victories did not mean that Indigenous people accepted Spanish rule; military conquest was followed by repeated resistance, negotiation, and uneven control.

Under encomienda, the Crown granted colonists claims to Indigenous tribute and labor, supposedly in exchange for protection and Christian instruction. This was not the same legal arrangement as ownership of land or chattel slavery, but it enabled severe coercion and abuse. Other labor demands, including mining drafts, further reorganized communities. As Indigenous populations declined and plantation production expanded, Spanish and Portuguese colonists increasingly relied on enslaved African labor.

Spanish authorities developed racial and social classifications that ranked ancestry and birthplace. These categories affected status without creating a completely fixed or uniform society; wealth, local circumstances, and negotiation mattered. Catholic missions sought conversion and imposed new practices, while Indigenous communities retained, blended, or adapted traditions.

Debates over conquest exposed contradictions within the empire. Bartolomé de las Casas criticized the abuse of Indigenous people, whereas defenders of conquest justified Spanish domination through claims about religion and civilization. Such arguments did not represent modern racial equality, and reforms did not eliminate exploitation. Their historical significance lies partly in showing that colonization generated moral and political disputes from within as well as resistance from colonized people. Analyze the distance between official justification and actual labor conditions rather than treating laws as proof of enforcement.`,
`Worked sourcing: Imagine a royal official defending a labor grant by emphasizing Christian instruction. Identify the audience and purpose: the official seeks approval within an imperial system that presents conversion as legitimate. The source helps explain how coercion was justified, but it cannot alone establish how workers experienced the arrangement. Pair it with evidence of tribute demands or Indigenous petitions. Sourcing means explaining why the author's position matters to the argument, not merely labeling the author biased.`,
`Do not equate encomienda with a land deed or assume that criticism immediately ended coercion. Las Casas's opposition to Indigenous exploitation did not automatically imply a consistently modern antislavery position throughout his life.`,
`Check: How can a law intended to limit abuse also reveal imperial priorities? Answer: It may restrain particular colonists while preserving tribute, conversion, and royal control. Reform and continued domination could therefore coexist within the same colonial policy.`,
[['Encomienda','A Spanish grant of claims to Indigenous tribute and labor, associated with obligations of protection and religious instruction; it was not simply a land grant.'],['Conquistador','A participant in Spanish military conquest in the Americas, often relying on Indigenous alliances as well as European resources.'],['Casta classification','Colonial Spanish categories of ancestry and status that helped organize hierarchy, though local social realities were more complex than a rigid chart.'],['Bartolomé de las Casas','A Spanish cleric who criticized the exploitation of Indigenous people and participated in debates over the legitimacy of conquest.']]);
chapter(2,1,'Regional Colonies and Atlantic Economies',
`English mainland colonies developed distinct economies because settlement goals, environments, labor supplies, and migration patterns interacted. In the Chesapeake, tobacco exports encouraged large landholdings and demand for labor. Early colonists relied heavily on indentured servants, whose contracts exchanged several years of work for passage and support. Disease, conflict, and unequal access to land shaped opportunity. Over the seventeenth century, planter wealth and a legally defined system of hereditary racial slavery expanded together.

New England's shorter growing season and migration by families encouraged mixed agriculture, fishing, commerce, and smaller farms. Puritan institutions connected church membership, local government, and moral regulation, although settlements differed and dissent produced new communities. Town meetings did not mean universal political participation: gender, property, religion, and status restricted access.

The Middle Colonies combined grain production, port trade, and religious and ethnic diversity. Pennsylvania's Quaker origins encouraged religious toleration, but toleration was not the same as equal political rights. In the Lower South, rice and later indigo plantations depended heavily on enslaved African labor. Enslaved people's agricultural knowledge and collective resistance shaped plantation societies despite the violence of enslavement.

These regional differences existed within a shared Atlantic economy. Colonial merchants traded with Britain, the Caribbean, and Africa; northern ports profited from commerce connected to slavery even where plantation agriculture was less common. Compare predominant patterns without imagining sealed regions or labeling the North free of enslavement. Economic connections can be as important as local differences when explaining colonial development.`,
`Worked comparison: Tobacco planters and New England merchants both participated in Atlantic markets. Their labor systems differed in scale and organization, but each benefited from trade structures involving enslaved labor. A strong answer specifies tobacco exports and shipping or provisioning, then explains how the commercial connection qualifies a simple North-versus-South contrast. Regional specialization did not prevent interdependence. The evidence supports both difference in local production and continuity in participation in an unequal Atlantic system.`,
`Avoid saying every New England settler sought religious freedom for everyone. Do not confuse a servant's fixed-term contract with hereditary enslavement or describe either labor system solely from an employer's perspective.`,
`Check: Why is a northern merchant's shipment of provisions to a Caribbean plantation relevant to slavery? Answer: It shows how commercial profits could depend on enslaved production even where the merchant's own region lacked the same plantation economy.`,
[['Indentured servitude','A fixed-term labor contract, often exchanged for passage; coercive conditions could be severe, but the status was legally distinct from hereditary chattel slavery.'],['Chesapeake tobacco economy','An export-oriented system in Virginia and Maryland that encouraged large estates and sustained demand for coerced labor.'],['Middle Colonies','Colonies including Pennsylvania and New York, associated with grain exports, ports, and considerable ethnic and religious diversity.'],['Rice plantation','A Lowcountry agricultural enterprise heavily dependent on enslaved African labor, skills, and environmental knowledge.']]);
chapter(2,2,'Slavery, Resistance, and Indigenous Power',
`Racial slavery in English North America developed through law and economic choice rather than appearing fully formed at the first arrival of Africans. Planters sought dependable labor for profitable exports. Colonial laws increasingly made enslaved status hereditary through the mother, limited mobility, and defined rights differently by ancestry. Such measures protected slaveholders' claims while hardening racial boundaries. Bacon's Rebellion in 1676 exposed conflicts among Virginia elites, poorer settlers, and Indigenous peoples, but no single event alone created slavery.

Enslaved Africans and their descendants resisted through escape, work slowdowns, cultural preservation, negotiation, and rebellion. The Stono Rebellion of 1739 in South Carolina illustrates armed resistance and the insecurity felt by slaveholding authorities. Its repression led to tighter restrictions, demonstrating how resistance and coercive law could reinforce one another without making enslaved people passive victims.

Indigenous nations continued to shape colonial development. They traded, made alliances, defended territory, and exploited rivalries among European powers. The Pueblo Revolt of 1680 expelled Spanish authorities from much of New Mexico for more than a decade; its causes included religious suppression and labor demands. In New England, Metacom's War in the 1670s devastated Indigenous and colonial communities and strengthened English territorial control after enormous violence.

The recurring issue was sovereignty: who could control land, labor, religion, and diplomacy? European claims on maps frequently exceeded actual authority. A complete account treats colonial expansion as contested and recognizes that Indigenous resistance could change imperial policy even when it did not permanently end colonization.`,
`Worked causation: Explain why a legislature might restrict enslaved people's movement after a rebellion. Begin with a specific threat to slaveholders' security, then connect that fear to expanded surveillance and legal control. Do not imply that repression removed resistance or justified it morally. In comparison, the Pueblo Revolt targeted Spanish religious and political authority, not a plantation slave code. Both involved coercion, but their institutions and immediate objectives differed.`,
`Do not treat slavery as inevitable, reduce all resistance to armed revolt, or assume an imperial boundary proved actual control. Distinguish the Indigenous leader Metacom from the English name King Philip used in many accounts.`,
`Check: What does the temporary success of the Pueblo Revolt reveal about Spanish power? Answer: Colonial authority depended on local cooperation and force; it could be overthrown by coordinated Indigenous resistance, even though Spain later reestablished control.`,
[['Hereditary racial slavery','A legal system linking enslaved status to descent and racial classification, making bondage inheritable and protecting slaveholders’ claims.'],['Bacon’s Rebellion','A 1676 uprising in Virginia reflecting class and frontier conflicts, including settler demands for attacks on Indigenous communities.'],['Stono Rebellion','A 1739 revolt by enslaved people in South Carolina followed by intensified restrictions and repression.'],['Pueblo Revolt','A 1680 uprising against Spanish rule in New Mexico motivated in part by coercive labor and suppression of Indigenous religious practices.']]);
chapter(2,3,'Religion, Enlightenment, and Imperial Regulation',
`Colonists lived within an empire that attempted to regulate trade while allowing considerable local self-government. Mercantilist policy treated colonies as sources of raw materials and markets for imperial commerce. Navigation laws sought to channel shipping and trade through English networks. Enforcement varied, and merchants sometimes evaded restrictions. The later phrase salutary neglect describes relatively loose supervision, not the absence of imperial laws or colonial resistance.

Colonial assemblies exercised meaningful authority over taxation and local affairs, while governors and imperial officials claimed royal power. These overlapping institutions gave many colonists experience arguing about consent, representation, and constitutional rights. Participation remained limited, but conflicts over assemblies established habits that later mattered in resistance to Parliament.

The Enlightenment emphasized reason and encouraged arguments about natural rights and government by consent. These ideas did not automatically produce democracy; slaveholders and imperial officials could adopt selected Enlightenment language while preserving hierarchy. The First Great Awakening, beginning in the 1730s, emphasized emotional conversion and religious renewal. It challenged some established ministers, encouraged new denominations, and expanded opportunities for lay participation. Its effects were uneven and included new divisions rather than a single unified colonial identity.

Print culture, colleges, revivals, and commercial networks spread arguments across colonial boundaries. Compare Enlightenment reasoning with revivalist appeals to spiritual experience: they offered different sources of authority, yet both could encourage people to question inherited institutions. Their relationship to the Revolution was indirect. An argument for long-term influence should identify how habits of criticism and organization developed, not claim that one sermon or philosophical text inevitably caused independence.`,
`Worked historical connection: A revival preacher challenges a wealthy established minister, while an assembly challenges a governor's spending request. These conflicts are not identical, but both raise questions about established authority. Explain the distinct setting before making a connection. Religious participation could expand without equal political participation, and assembly privileges could coexist with imperial loyalty. A qualified argument recognizes that challenges to authority created resources for later resistance without requiring colonists already to favor independence.`,
`Do not confuse the First Great Awakening with nineteenth-century reform revivals. Mercantilism is not unrestricted free trade. Colonial assemblies were neither fully independent legislatures nor institutions representing every resident equally.`,
`Check: Why does weak enforcement of trade rules differ from the absence of rules? Answer: Existing laws gave imperial officials a basis for later intervention; stricter enforcement could therefore transform an old legal framework into a new political grievance.`,
[['Mercantilism','An imperial approach seeking national power through regulated commerce, favorable trade relationships, and colonial economic resources.'],['Navigation Acts','English trade laws intended to channel colonial shipping and commerce through imperial networks.'],['First Great Awakening','Eighteenth-century Protestant revivals emphasizing conversion and renewal, producing challenges to established clergy and denominational divisions.'],['Enlightenment','An intellectual movement emphasizing reason and inquiry, including influential arguments about natural rights and legitimate government.']]);
chapter(3,1,'From Imperial War to Independence',
`The Seven Years' War transformed the relationship between Britain and its North American colonies. Britain's victory in 1763 removed France from much of mainland North America but left substantial debt and new governing responsibilities. Imperial officials wanted colonists to contribute to military costs and follow policies limiting western conflict. The Proclamation of 1763 sought to restrict settlement west of the Appalachian boundary, angering settlers and speculators while failing to eliminate Indigenous sovereignty disputes.

Colonial resistance intensified when Parliament imposed new revenue measures and tightened enforcement. The Stamp Act taxed printed materials; later Townshend duties targeted imports. Critics argued that taxation without colonial consent violated their rights as British subjects. Their claim was not simply that taxes were high: it concerned who possessed legitimate authority. Parliament defended its sovereignty and the idea of virtual representation, while colonists emphasized their own elected assemblies.

Boycotts, committees, petitions, and crowd actions created new forms of cooperation. Women participated through nonconsumption and production, although political leadership remained unequal. Escalating confrontation, including the Coercive Acts after the Boston Tea Party, helped persuade many colonists that reconciliation was unlikely. Others remained loyal to Britain or tried to remain neutral.

Independence in 1776 was therefore a contested outcome, not the automatic consequence of longstanding unity. The Declaration combined natural-rights arguments with specific charges against the king. Its universal language became a resource for groups excluded from full equality, including enslaved people and women, even as many revolutionary leaders defended slavery and restricted political participation.`,
`Worked argument: To explain why war led to revolution, connect British debt to revenue policies, policies to constitutional objections, and resistance to escalating repression. The causal chain is stronger than listing the Stamp Act, Tea Party, and Declaration in sequence. Include a qualification: many colonists initially sought rights within the empire. The movement changed objectives as repeated confrontations undermined trust, and Patriot success did not mean all residents supported independence.`,
`Do not say the Proclamation ended westward migration or that the Declaration immediately abolished slavery. Distinguish a constitutional objection to taxation from a simple complaint about the size of a particular tax.`,
`Check: How did boycotts broaden political participation without creating equal voting rights? Answer: Consumers and producers, including many women, could influence imperial commerce through coordinated action even when formal electoral institutions continued to exclude them.`,
[['Proclamation of 1763','An imperial boundary policy seeking to limit western colonial settlement and conflict after the Seven Years’ War.'],['Virtual representation','The British argument that Parliament represented the interests of the empire generally, even where residents did not elect its members.'],['Nonimportation','Organized refusal to buy imported goods, used by colonists to pressure British merchants and policymakers.'],['Declaration of Independence','The 1776 statement asserting separation from Britain through natural-rights principles and a list of grievances.']]);
chapter(3,2,'Constitutional Design and Ratification',
`The Articles of Confederation reflected Americans' fear of concentrated authority after independence. The national government could conduct diplomacy and wage war but depended on states for revenue and lacked an independent executive capable of enforcing its decisions. Interstate disputes and financial instability exposed weaknesses, while the Northwest Ordinance demonstrated that the Confederation could establish procedures for territorial government. The system was limited, not entirely inactive.

The Constitutional Convention of 1787 proposed a stronger federal government with separate legislative, executive, and judicial branches. The Great Compromise combined population-based representation in the House with equal state representation in the Senate. Federalism divided authority between national and state governments, while checks and balances distributed powers within the national government.

Compromises over slavery protected slaveholders' influence. The Three-Fifths Compromise increased representation for slaveholding states without giving enslaved people political rights. Restrictions on ending the international slave trade before 1808 protected the trade temporarily; they did not guarantee slavery would end afterward. Constitutional design must be analyzed as both a response to governing problems and a distribution of power among unequal interests.

Federalists argued that the proposed system could control faction and govern effectively. Anti-Federalists feared distant consolidated power and insufficient safeguards for liberty. Ratification depended partly on assurances that amendments would protect rights. The Bill of Rights limited the new national government's authority; most protections were not initially enforced against state governments through modern incorporation doctrine. Debate over the Constitution continued after adoption because its meaning and the boundaries of federal power remained contested.`,
`Worked comparison: Compare an Anti-Federalist concern about a distant legislature with a Federalist argument for an extended republic. Both could claim to defend republican liberty. They disagreed about whether size and institutional complexity would protect citizens from oppressive majorities or reduce accountability. Explain the competing mechanisms rather than assigning one side the label democratic. Ratification was a debate within the revolutionary inheritance, and a bill of rights became a practical response to concerns about the new government's reach.`,
`The Three-Fifths Compromise did not count enslaved people as voters or confer partial citizenship. Do not say the Bill of Rights immediately applied to all state actions or that federalism means complete state independence.`,
`Check: Why can the Constitution be described as both a solution and a compromise? Answer: It addressed revenue and enforcement problems while allocating representation and protecting powerful interests, including slavery, through negotiated arrangements.`,
[['Articles of Confederation','The first national governing framework, creating a confederation with limited central authority and dependence on state cooperation.'],['Great Compromise','The convention agreement establishing population-based House representation and equal representation of states in the Senate.'],['Three-Fifths Compromise','A representation and direct-taxation formula that increased slaveholding states’ political power without enfranchising enslaved people.'],['Anti-Federalists','Opponents of the proposed Constitution who raised concerns about centralized power, representation, and insufficient protections for liberty.']]);
chapter(3,3,'Politics and Power in the Early Republic',
`The Washington administration tested the new Constitution through decisions about finance, executive power, and foreign relations. Alexander Hamilton proposed federal assumption of state debts, funding of national debt, and a national bank. He aimed to stabilize public credit and connect wealthy investors to the federal government's success. Opponents feared concentrated financial power and disputed whether the Constitution authorized a bank.

Thomas Jefferson and James Madison favored an agrarian vision and a narrower reading of federal authority, although their own policies could depart from that position. The controversy helped produce Federalist and Democratic-Republican parties. Party formation was not simply a contest between good government and its enemies; it reflected different economic interests, constitutional interpretations, and responses to European events.

The French Revolution and warfare between Britain and France intensified domestic divisions. Washington pursued neutrality, and the Jay Treaty sought to reduce conflict with Britain, angering critics who viewed it as too accommodating. The Alien and Sedition Acts under John Adams expanded federal power and punished some criticism of the government. The Virginia and Kentucky Resolutions responded by challenging the constitutionality of those acts, contributing to continuing debate over state and federal authority.

The election of 1800 brought a transfer of national power between rival parties. This was a significant test of republican institutions, but it did not create universal political inclusion. Meanwhile, federal policies and military campaigns intensified pressure on Indigenous nations. The Treaty of Greenville followed U.S. military victory in the Northwest and facilitated land cessions. Democratic expansion for some white settlers could accompany dispossession and exclusion for others.`,
`Worked continuity and change: Hamilton's bank controversy and the Sedition Act both involved federal power, but their purposes differed. The bank concerned economic administration and implied powers; the Sedition Act concerned dissent during international tension. A careful argument identifies a continuing constitutional dispute while distinguishing the policies. Use the 1800 transfer as evidence of institutional resilience, then qualify that claim with restricted voting and continuing coercion beyond the electorate.`,
`Do not confuse Jefferson's Democratic-Republicans with the later Republican Party. Neutrality did not mean isolation from trade. The peaceful transfer of presidential power did not eliminate partisan conflict or expand equal rights to every group.`,
`Check: How did the bank controversy contribute to party development? Answer: Disagreement over implied powers and economic priorities organized recurring alliances around competing visions of the republic, turning policy disputes into durable political opposition.`,
[['Hamilton’s financial program','Federal policies promoting public credit, debt assumption, and a national bank to strengthen government and commercial development.'],['Implied powers','Powers understood as reasonably necessary to carry out enumerated constitutional powers, central to debate over the national bank.'],['Alien and Sedition Acts','1798 laws expanding federal authority over immigrants and punishing certain criticism, provoking constitutional opposition.'],['Election of 1800','A transfer of national power from Federalists to Democratic-Republicans that demonstrated the survival of competitive republican politics.']]);
chapter(4,1,'Market Revolution and Unequal Opportunity',
`During the early nineteenth century, transportation and communications networks connected regional economies more closely. Roads, canals, steamboats, and later railroads reduced the cost of moving goods and people. The Erie Canal linked interior farms to eastern markets and helped make New York City a leading commercial center. These developments did not replace local economies everywhere, but they encouraged farmers and manufacturers to produce for distant buyers.

Industrial production also changed the organization of labor. Textile mills concentrated workers and machinery under employers who regulated time and output. Lowell mills recruited many young women from New England farms, offering wages and supervised housing while imposing demanding schedules. Workers could experience both new independence and loss of control over their labor. Labor organizing challenged hours, pay, and employer authority, although early unions faced substantial obstacles.

The cotton gin increased the profitability of processing short-staple cotton. Together with textile demand, land expansion, and federal support for dispossession, it helped drive the spread of slavery into the Deep South. Industrialization and plantation slavery were therefore interconnected rather than opposing economic worlds. Northern finance, shipping, and manufacturing benefited from cotton produced by enslaved labor.

The Market Revolution created opportunities unevenly. Commercial success depended on access to credit, land, transportation, and legal rights. Economic downturns exposed households to distant market forces, while wage work and migration disrupted older relationships. Explain technological change through institutions and people: a canal mattered because investors, governments, merchants, and workers organized its construction and use. Technology by itself did not determine who received its benefits.`,
`Worked causal explanation: Connect the cotton gin to slavery without claiming a machine invented the institution. Faster processing increased potential cotton profits; textile demand and access to new land encouraged planting; slaveholders then purchased and forcibly relocated enslaved people. The mechanism passes through prices, investment, and coercion. Compare Lowell wage labor: workers could leave legally, unlike enslaved laborers, though economic need and restrictive workplace rules limited their choices. Similar participation in production did not erase the fundamental legal difference.`,
`Do not describe industrialization as ending slavery or treat a wage contract as identical to chattel bondage. Avoid claiming every farmer immediately abandoned subsistence or that transportation projects benefited all regions equally.`,
`Check: How could a canal alter farming decisions? Answer: Lower shipping costs could make distant sales profitable, encouraging specialization and commercial production; farmers might gain income while becoming more vulnerable to changing prices and credit conditions.`,
[['Market Revolution','The expansion of commercial exchange and changes in transportation, communication, production, and labor in the early nineteenth century.'],['Erie Canal','The waterway opened in 1825 linking the Great Lakes region with the Hudson River and Atlantic commerce.'],['Lowell system','Textile production employing many young women under factory schedules and supervised boarding arrangements in Massachusetts.'],['Cotton gin','A device that accelerated cotton processing and helped make slave-grown short-staple cotton more profitable.']]);
chapter(4,2,'Democracy, Federal Power, and Removal',
`Political participation among white men expanded as many states reduced property requirements for voting. Parties built mass organizations, newspapers, rallies, and patronage networks. This expansion did not include women, most free Black people, enslaved people, or Indigenous nations. Analyze democracy by asking who gained access and who remained excluded, rather than treating the period as either wholly democratic or wholly unchanged.

Andrew Jackson presented himself as a defender of ordinary citizens against privileged institutions. His veto of the national bank's recharter expressed hostility to concentrated financial power, but his administration also strengthened executive authority. The Bank War concerned constitutional interpretation, economic interests, and political legitimacy. Opposition to Jackson helped create the Whig Party, which generally favored a more active federal role in economic development.

The nullification crisis revealed different views of sovereignty. South Carolina challenged federal tariffs, claiming the right to invalidate federal law. Jackson rejected nullification and supported enforcement, while compromise lowered tariffs. This dispute should be distinguished from later secession even though both involved state resistance to federal authority.

Jackson's support for Indian removal exposes the limits of white democratic expansion. The Indian Removal Act of 1830 promoted the forced relocation of southeastern Indigenous nations. The Cherokee pursued legal and diplomatic resistance; Worcester v. Georgia rejected Georgia's authority within Cherokee territory, but removal proceeded. The Trail of Tears under Martin Van Buren involved deaths, dispossession, and coercion. Federal policy expanded settlers' access to land while violating Indigenous rights and sovereignty.`,
`Worked qualification: A thesis might argue that Jacksonian politics expanded participation within the white male electorate while strengthening exclusion outside it. Support the first clause with changing suffrage rules and party mobilization, and the second with removal. Explain that these were connected: settlers' political power encouraged demands for Indigenous land. Do not use the same evidence to claim every poor white man gained wealth or that all Indigenous communities followed identical strategies of resistance.`,
`Jackson did not personally lead every removal, and the major Cherokee expulsion occurred during Van Buren's presidency. Do not interpret a ruling favorable to Cherokee sovereignty as proof that federal officials enforced Indigenous rights.`,
`Check: Why does opposition to the bank not prove opposition to all strong government? Answer: Jackson attacked one national institution while using executive power vigorously in other areas, including removal and resistance to nullification.`,
[['Jacksonian democracy','Mass party politics and expanded white male participation associated with Jackson’s era, alongside persistent racial and gender exclusions.'],['Nullification','The claim that a state could invalidate a federal law within its borders, central to South Carolina’s tariff confrontation.'],['Indian Removal Act','The 1830 law authorizing removal negotiations that facilitated coercive expulsion of southeastern Indigenous nations.'],['Worcester v. Georgia','An 1832 ruling rejecting Georgia’s jurisdiction within Cherokee territory, illustrating a gap between legal protection and political enforcement.']]);
chapter(4,3,'Revivals, Reform, and Antislavery',
`The Second Great Awakening emphasized conversion, moral responsibility, and the possibility of personal transformation. Many reformers extended these ideas to society, organizing voluntary associations against perceived social problems. Temperance campaigns, prison reform, expanded education, and missionary work reflected this impulse, though reform also involved secular arguments and differing religious traditions. Reformers often sought to improve lives while imposing standards of discipline on others.

Antislavery activism changed in important ways. Earlier gradual emancipation and colonization proposals coexisted with a growing movement demanding immediate abolition. Black activists, including formerly enslaved speakers and writers, challenged slavery and racial exclusion directly. Frederick Douglass combined personal testimony with political argument; William Lloyd Garrison advocated immediate emancipation and denounced compromises with slavery. Abolitionists disagreed about political action, violence, religion, and gender equality.

Women gained organizational experience in reform movements but faced restrictions within them. The Seneca Falls Convention of 1848 articulated demands for women's rights, including suffrage. Its Declaration of Sentiments adapted revolutionary language to expose gender hierarchy. This did not create a uniform movement: race, class, strategy, and the relationship to abolition produced continuing disagreement.

Reform reveals both change and limits. Public schooling expanded in some places, yet access and curricula varied by race and region. Utopian communities experimented with property and family arrangements without transforming society as a whole. A defensible explanation connects reform to religious revival, market changes, print networks, and expanding voluntary organization rather than reducing every movement to a single cause. Resistance from established interests also shaped what reform could accomplish.`,
`Worked comparison: Immediate abolitionists and temperance reformers both used lectures, newspapers, petitions, and associations. Their targets differed: abolition challenged a foundational property and racial system, whereas temperance often framed alcohol as a cause of household distress and disorder. Explain the shared organizational methods, then evaluate differences in social opposition. Women could gain a public voice through both movements while confronting exclusion from formal power and from leadership within some reform organizations.`,
`Do not equate colonization with racial equality or assume all abolitionists endorsed women's suffrage. Separate a movement's stated ideals from participation limits, and distinguish immediate abolition from proposals for gradual emancipation.`,
`Check: How did reform participation contribute to women's rights activism? Answer: Organizing petitions and meetings developed political skills, while exclusion from leadership made unequal treatment visible and encouraged demands extending beyond any single reform cause.`,
[['Second Great Awakening','Nineteenth-century Protestant revivals emphasizing conversion and moral responsibility, contributing to several reform movements.'],['Immediate abolition','The demand to end slavery without gradual schedules or compensation-based delay, associated with a radical antislavery movement.'],['Seneca Falls Convention','An 1848 women’s rights gathering whose Declaration of Sentiments challenged gender inequality and demanded suffrage.'],['Temperance','A movement seeking to reduce or eliminate alcohol consumption, often linking reform to family welfare and social discipline.']]);
chapter(5,1,'Expansion and the Sectional Crisis',
`Expansion intensified conflict over slavery because new territories forced Americans to debate the institution's future. Manifest Destiny presented continental expansion as a national mission, often overlooking the sovereignty of Indigenous nations and Mexico. The annexation of Texas and disputed boundaries contributed to the U.S.-Mexican War. The Treaty of Guadalupe Hidalgo in 1848 transferred a vast region to the United States, creating immediate disputes about slavery's legal status there.

The Wilmot Proviso proposed barring slavery from territory acquired from Mexico. It did not become law, but the debate exposed sectional divisions. The Compromise of 1850 admitted California as a free state and included a strengthened Fugitive Slave Act. That law extended federal enforcement into northern communities and intensified opposition by requiring cooperation with the return of alleged fugitives while denying important procedural protections.

The Kansas-Nebraska Act of 1854 applied popular sovereignty and effectively repealed the Missouri Compromise restriction in those territories. Rival settlers and governments in Kansas demonstrated that a popular vote did not peacefully resolve fundamental conflicts over slavery and legitimacy. Violence and party realignment followed; the Republican Party organized against slavery's expansion rather than initially demanding immediate emancipation everywhere.

Dred Scott v. Sandford in 1857 denied Black national citizenship and asserted that Congress could not prohibit slavery in federal territories. Rather than settling the controversy, it deepened distrust. By 1860, competing constitutional interpretations, moral claims, economic interests, and political breakdown had made earlier compromises increasingly difficult. Slavery was central to the sectional crisis, even when participants framed disputes through states' rights or federal power.`,
`Worked causation: Explain why western expansion destabilized politics by connecting territorial acquisition to the balance of slave and free states, then to disputes over congressional authority. Use Kansas-Nebraska to show how one proposed solution generated new conflict. A claim that geography alone caused war misses the issue: expansion became explosive because slavery's future and political power were at stake. Acknowledge that territorial disputes interacted with abolitionism, racial fears, and collapsing national parties.`,
`Popular sovereignty did not guarantee fair participation or peace. Do not call the Wilmot Proviso enacted law, and do not detach the phrase states' rights from the particular right slaveholding leaders sought to protect.`,
`Check: Why did the Fugitive Slave Act intensify conflict outside the South? Answer: Its enforcement requirements and restrictions on alleged fugitives involved northern residents directly in sustaining slavery, turning a sectional institution into an immediate local political and moral confrontation.`,
[['Manifest Destiny','An expansionist belief that the United States was destined to spread across the continent, used to justify conquest and displacement.'],['Wilmot Proviso','An unsuccessful proposal to prohibit slavery in territory acquired from Mexico, revealing sectional divisions.'],['Popular sovereignty','The proposal that territorial settlers should decide slavery’s status, associated with escalating conflict in Kansas.'],['Dred Scott v. Sandford','The 1857 Supreme Court decision denying Black national citizenship and rejecting congressional power to ban slavery in federal territories.']]);
chapter(5,2,'Civil War and Emancipation',
`Secession followed Abraham Lincoln's election in 1860, when slaveholding leaders feared the future of slavery within a Union governed by an antiexpansion party. Confederate leaders explicitly defended slavery, even though individual soldiers' motives varied. The war began over the Union's survival and expanded into a struggle over emancipation. Distinguish the reasons governments entered the conflict from all the goals that developed during it.

The Union possessed major advantages in population, manufacturing, transportation, and financial resources. These advantages did not guarantee a quick victory: the Confederacy could pursue a defensive strategy, and military leadership, geography, diplomacy, and public morale shaped the war's course. Federal mobilization expanded through taxation, borrowing, conscription, and measures supporting economic development.

Enslaved people influenced emancipation by escaping to Union lines, providing labor and intelligence, and pressing officials to confront slavery as a military and political issue. The Emancipation Proclamation, effective in 1863, applied to areas in rebellion rather than abolishing slavery everywhere immediately. Its enforcement depended on Union military success. It also authorized Black military service, strengthening the Union war effort and making emancipation a central war aim.

Black soldiers served despite discrimination and unequal treatment. Women sustained households, farms, hospitals, and reform efforts while wartime demands disrupted existing gender roles without eliminating hierarchy. The Thirteenth Amendment abolished slavery nationally, except as punishment for crime after conviction. Emancipation thus emerged through the interaction of enslaved people's actions, military developments, political decisions, and constitutional change. No single proclamation fully explains either the destruction of slavery or the struggle over freedom that followed.`,
`Worked change over time: Compare federal policy in 1861 with policy after 1863. Identify the initial emphasis on preserving the Union, then explain how escape, military necessity, abolitionist pressure, and presidential decisions broadened the war's aims. Use the Proclamation as evidence of change but qualify its reach. The Thirteenth Amendment supplies evidence for a later national legal transformation. Chronology allows an argument about development instead of attributing every outcome to Lincoln alone.`,
`The Proclamation did not immediately free every enslaved person or apply identically to loyal border states. Do not explain Confederate secession solely through tariffs, and do not treat Union resource advantages as a guarantee of effortless victory.`,
`Check: How did Black military service influence the meaning of the war? Answer: It strengthened the military campaign against the Confederacy while making claims to freedom and citizenship harder to separate from the Union's victory.`,
[['Secession','Withdrawal claimed by southern states from the Union, undertaken by leaders seeking above all to protect slavery’s future.'],['Emancipation Proclamation','Lincoln’s wartime order applying emancipation to designated areas in rebellion and authorizing Black enlistment.'],['United States Colored Troops','Union military units of Black soldiers whose service advanced the war effort and claims to citizenship.'],['Thirteenth Amendment','The constitutional amendment abolishing slavery and involuntary servitude except as punishment for crime after conviction.']]);
chapter(5,3,'Reconstruction and Contested Citizenship',
`Reconstruction concerned how former Confederate states would return and what freedom would mean after slavery. Presidential approaches under Lincoln and Andrew Johnson emphasized relatively rapid restoration, but congressional Republicans increasingly demanded federal protection of civil and political rights. Southern Black Codes attempted to limit freedpeople's autonomy and labor choices, revealing that emancipation did not automatically produce equal citizenship.

The Fourteenth Amendment established national birthright citizenship, with specified jurisdictional limits, and guaranteed equal protection and due process. The Fifteenth Amendment prohibited denial of voting rights on account of race, color, or previous condition of servitude; it did not establish universal suffrage. Congressional Reconstruction placed much of the former Confederacy under military supervision while establishing requirements for readmission.

Freedpeople pursued family reunification, education, religious institutions, landownership, and political participation. Black officeholding and biracial governments expanded democracy, though opposition portrayed these governments through racist stereotypes. The Freedmen's Bureau provided assistance and supported education but lacked resources and consistent political backing. Most formerly enslaved families did not receive land, and sharecropping often tied households to debt and dependence.

White supremacist violence, including Ku Klux Klan attacks, aimed to destroy Black political power. Federal enforcement sometimes countered this violence, but northern commitment weakened amid political conflict, economic depression, and racism. The contested election of 1876 and withdrawal of remaining troops in 1877 symbolize Reconstruction's end, not the disappearance of every federal law. Constitutional amendments remained available for future rights struggles even as disfranchisement and segregation expanded. Reconstruction was both an extraordinary constitutional transformation and an incomplete, violently resisted redistribution of power.`,
`Worked evaluation: An argument that Reconstruction failed must specify the outcome being judged. Federal protection and land redistribution were deeply limited, while emancipation and constitutional citizenship represented lasting changes. Explain how terror and economic dependency restricted the practical exercise of legal rights. A stronger thesis recognizes both achievements and reversals rather than treating 1877 as a moment when the amendments vanished. Freedpeople's agency belongs in the explanation alongside decisions by presidents and Congress.`,
`The Fifteenth Amendment did not enfranchise women or forbid every voting restriction. Sharecropping was not legally identical to slavery, but freedom of contract did not prevent coercion, debt, and violence. Avoid the discredited claim that Black political participation caused Reconstruction’s problems.`,
`Check: Why did constitutional amendments not ensure equal participation? Answer: Legal protections required enforcement, and violence, discriminatory administration, and economic pressure could block their exercise even when the constitutional language remained unchanged.`,
[['Fourteenth Amendment','An amendment establishing national citizenship and protections including due process and equal protection.'],['Fifteenth Amendment','An amendment prohibiting racial discrimination in voting, without establishing universal suffrage or preventing every later restriction.'],['Freedmen’s Bureau','A federal agency assisting formerly enslaved people and others after the war, notably through education and labor-related support.'],['Sharecropping','An agricultural arrangement exchanging a share of the crop for access to land and supplies, often producing debt and dependency.']]);
chapter(6,1,'Industrial Capitalism and Labor Conflict',
`After the Civil War, corporations expanded production through new technologies, national markets, finance, and reorganized management. Railroads connected regions and received substantial public assistance through land grants and other support. Their growth stimulated steel, coal, and manufacturing while provoking disputes over rates, land, corruption, and labor conditions. Industrial capitalism depended on government decisions as well as private entrepreneurship.

Business leaders pursued different strategies. Horizontal integration combined competitors in the same industry, while vertical integration brought successive stages of production and distribution under one firm. Economies of scale could reduce costs, but concentrated power also restricted competition and strengthened employers' influence. Arguments associated with Social Darwinism presented inequality as a natural outcome of competition; critics instead emphasized exploitation and structural advantage.

Workers experienced wage opportunities alongside dangerous workplaces, long hours, economic insecurity, and unequal treatment. The Knights of Labor sought broad organization, while the American Federation of Labor generally concentrated on skilled workers and practical workplace demands. Their memberships and strategies differed, and neither represented all workers equally. Strikes such as the Great Railroad Strike, Homestead, and Pullman revealed tensions among employers, unions, courts, and state power.

Federal and state officials often intervened against strikers, using troops or injunctions to protect transportation and property. Public opinion could turn against labor after violence or claims of radicalism. Yet repression did not end organizing, and industrial conflict made questions of corporate responsibility and workers' rights central to national politics. Evaluate gains in output separately from the distribution of wealth and control: rising national production does not prove that all households gained security.`,
`Worked comparison: A vertically integrated steel company controls raw materials, mills, and transport; a horizontally integrated refiner buys rival refineries. Both may reduce competition, but the organizational mechanisms differ. Connect that distinction to bargaining power: a large employer can withstand disruption differently from an individual worker. Then use a strike to explain how government intervention shaped the balance. The state was an active participant, not simply an observer of a private disagreement.`,
`Do not confuse vertical and horizontal integration or assume laissez-faire rhetoric meant government never supported business. Avoid describing labor as a single unified group without differences in skill, race, gender, and strategy.`,
`Check: Why are railroad land grants evidence against a purely private account of industrialization? Answer: They show that public resources and political choices helped build the infrastructure through which private corporations accumulated wealth and expanded markets.`,
[['Vertical integration','Control of multiple stages of a production and distribution process within one business organization.'],['Horizontal integration','Combining competing firms at the same stage of production to expand market control.'],['Knights of Labor','A broad late-nineteenth-century labor organization that sought to unite many categories of workers and promote social reform.'],['American Federation of Labor','A federation generally emphasizing skilled trade unions and practical demands over wages, hours, and conditions.']]);
chapter(6,2,'Western Expansion and Indigenous Dispossession',
`Federal policy encouraged western settlement through land legislation, railroad construction, military campaigns, and support for resource extraction. The Homestead Act offered land under specified conditions, but acquiring a claim did not guarantee a successful farm. Water shortages, debt, transportation costs, and environmental risks shaped settlers' lives. Railroad companies, large ranchers, miners, and commercial agriculture also exercised substantial power, challenging the image of a West built only by independent family farmers.

For Indigenous nations, expansion brought warfare, broken agreements, confinement, and efforts to transform cultural life. The destruction of buffalo herds undermined the economies of many Plains communities. Military campaigns and reservation policies restricted mobility and sovereignty. Indigenous people resisted through armed defense, diplomacy, legal claims, religious movements, and adaptation.

The Dawes Act of 1887 attempted to divide communally held reservation land into individual allotments. Officials claimed that private farming and assimilation would promote citizenship, but allotment opened so-called surplus lands to non-Indigenous settlement and contributed to enormous land loss. Boarding schools attempted to suppress Indigenous languages and practices. These policies sought not only territory but also cultural transformation.

The Ghost Dance expressed religious hopes in a context of dispossession; U.S. authorities treated the movement as a threat. The killing of Lakota people at Wounded Knee in 1890 demonstrates the violence accompanying federal control. Avoid portraying Indigenous history as ending there. Communities preserved identities and continued political struggles into the twentieth century and beyond. Western development was a process of environmental change, corporate growth, settlement, and contested sovereignty rather than an inevitable march across vacant land.`,
`Worked analysis of policy: A federal report praises individual landownership as civilization. Explain how its purpose reflects an assimilationist belief that Indigenous communal landholding should disappear. Then compare the stated benefit with the effect: allotment and sales transferred land out of Indigenous control. This is not enough to conclude every reformer had the same motive, but it shows how paternalistic language could support dispossession. Evaluate outcomes with evidence rather than accepting official descriptions at face value.`,
`The Homestead Act did not distribute empty land or ensure prosperity. Do not equate allotment with protection of tribal sovereignty, and do not describe Wounded Knee as the disappearance of Indigenous peoples or resistance.`,
`Check: Why could individual citizenship and land allotment threaten collective rights? Answer: A policy might recognize individuals while weakening tribal authority, communal ownership, and control over territory, allowing formal inclusion to coexist with dispossession.`,
[['Homestead Act','An 1862 law offering qualifying settlers land under residency and improvement conditions, within a broader process of Indigenous dispossession.'],['Dawes Act','An 1887 allotment law dividing reservation lands and facilitating extensive transfers out of Indigenous ownership.'],['Assimilation','Pressure or policy seeking to replace a group’s cultural practices with those of a dominant society.'],['Ghost Dance','A late-nineteenth-century Indigenous religious movement expressing renewal and hope amid conquest and dispossession.']]);
chapter(6,3,'Cities, Race, and Agrarian Protest',
`Industrial growth and migration expanded cities, where newcomers built communities while confronting crowded housing, dangerous work, and unequal services. Immigrants arrived from multiple regions; later nineteenth-century migration included growing numbers from southern and eastern Europe. Political machines provided assistance and connections while exchanging services for votes and engaging in corruption. Their appeal cannot be explained solely by ignorance: they met needs that formal public institutions often neglected.

Nativists portrayed immigrants as threats to labor, culture, or political order. The Chinese Exclusion Act of 1882 established a major federal restriction targeting Chinese labor immigration and reflected racialized opposition in the West. Different immigrant groups faced distinct legal and social barriers. At the same time, settlement houses sought to provide education and services, sometimes combining assistance with pressure to adopt middle-class norms.

In the South, white supremacist governments narrowed Black political participation through violence and devices such as poll taxes and literacy tests. Plessy v. Ferguson in 1896 upheld legally mandated racial segregation under the separate-but-equal doctrine. Black activists resisted through journalism, organizations, education, and community institutions; Ida B. Wells's anti-lynching work exposed the violence sustaining racial hierarchy.

Farmers confronted low commodity prices, debt, railroad charges, and tight credit. Alliances and the Populist Party proposed monetary expansion, railroad reform, and other changes to economic power. Their coalition had limits, including racial divisions, but it challenged the assumption that farmers' difficulties were purely individual failings. Compare urban and rural protest by identifying shared concerns about concentrated power alongside different institutions and immediate demands.`,
`Worked comparison: A farmer demands lower railroad rates while a city worker demands shorter hours. Both question the distribution of power in an industrial economy, but one focuses on the cost of marketing crops and the other on employment conditions. Explain their different positions before identifying a shared concern. Likewise, a machine's assistance to an immigrant family can coexist with corruption. Historical evaluation should recognize the practical function of an institution without treating that function as an excuse for every action.`,
`Do not confuse Populists with all later Progressives or assume farmers had a single racial politics. Separate immigration restrictions from citizenship rules, and remember that separate-but-equal was a legal doctrine contradicted by unequal realities.`,
`Check: Why is Wells's journalism evidence of agency under Jim Crow? Answer: She investigated and challenged justifications for racial violence, demonstrating organized resistance rather than acceptance of the institutions that restricted Black rights.`,
[['Political machine','An urban organization exchanging assistance, jobs, and connections for political support, often accompanied by corruption.'],['Chinese Exclusion Act','An 1882 federal law restricting Chinese labor immigration, reflecting racialized nativism.'],['Plessy v. Ferguson','The 1896 Supreme Court decision upholding segregation under the separate-but-equal doctrine.'],['Populist Party','A political movement advocating reforms such as monetary expansion and regulation of concentrated economic power, rooted substantially in agrarian protest.']]);
chapter(7,1,'Progressivism and Overseas Empire',
`Around the turn of the twentieth century, reformers sought responses to industrial concentration, corruption, urban problems, and changing social relationships. Progressivism was a collection of movements rather than one ideology. Journalists exposed abuses, settlement workers investigated conditions, and organizations campaigned for labor protections, public health, women's suffrage, and political reform. Some reformers promoted democratic participation while others favored expert administration or excluded groups through racial and nativist assumptions.

Federal regulation expanded through antitrust actions, food and drug legislation, and financial reform. Theodore Roosevelt argued for a more active federal role, but distinguishing good and bad combinations did not mean dismantling every large corporation. Woodrow Wilson's administration created the Federal Reserve and pursued additional economic regulation while segregating parts of the federal workforce. Reform and racial exclusion could advance together.

Overseas expansion raised related questions about power and citizenship. The Spanish-American War of 1898 increased U.S. influence in the Caribbean and Pacific. The United States acquired Puerto Rico, Guam, and the Philippines, while Cuba's formal independence existed alongside strong U.S. constraints. Filipino resistance to American rule challenged claims that expansion simply delivered freedom.

Supporters invoked strategic markets, naval power, racial hierarchy, and national mission. Anti-imperialists raised constitutional, moral, and practical objections, but they did not all support racial equality. Connect imperial expansion to earlier continental expansion while identifying differences: governing overseas territories without a clear path to statehood created distinctive constitutional problems. Domestic reform and international intervention both expanded federal activity, though their supporters' purposes and the people affected differed.`,
`Worked complexity: Evaluate the claim that Progressivism made government more democratic. Direct election of senators and women's suffrage expanded participation, while racial exclusion and expert commissions complicate a simple conclusion. Acknowledge both without canceling them into a vague mixed judgment. Specify the dimension: electoral access improved for some populations while administrative authority expanded and segregation persisted. Compare overseas rule, where the language of improvement also coexisted with unequal access to political power.`,
`Do not treat all Progressives as racial egalitarians or all anti-imperialists as supporters of Filipino equality. Distinguish Cuban formal independence from complete freedom of action under U.S. influence.`,
`Check: Why is federal workplace segregation relevant to evaluating Wilson's reforms? Answer: It demonstrates that expanding economic regulation did not necessarily produce equal treatment; progress in one area could coexist with intensified exclusion in another.`,
[['Progressivism','Diverse reform movements addressing industrial, urban, and political problems through regulation, participation, expertise, and social action.'],['Muckraker','A journalist associated with exposing corruption, corporate abuse, or social conditions to encourage reform.'],['Federal Reserve','The central banking system established in 1913 to help manage currency, banking, and financial stability.'],['Anti-imperialism','Opposition to overseas empire based on varying constitutional, moral, racial, or practical arguments, not a single uniform position.']]);
chapter(7,2,'World War I and the Contested 1920s',
`The United States entered World War I in 1917 after years of neutrality, growing economic connections to the Allies, and conflict over German submarine warfare. The Zimmermann telegram intensified fears, but no single incident alone explains intervention. Wilson framed participation in terms of democracy and a new international order, while wartime mobilization expanded federal management of production, finance, information, and labor.

The Espionage and Sedition Acts restricted dissent. Propaganda encouraged loyalty, while coercion and suspicion targeted critics and some immigrant communities. Black Americans' Great Migration from the South reflected both industrial labor opportunities and efforts to escape Jim Crow violence and restrictions. Military service and migration encouraged claims to fuller citizenship without eliminating discrimination.

After the war, the Senate rejected U.S. membership in the League of Nations amid disagreement over international obligations and executive authority. The United States remained economically and diplomatically active, so rejection of the League did not mean complete isolation. The Red Scare, labor unrest, and racial violence showed the instability of the transition from war.

The 1920s combined consumer expansion with deep inequalities. Automobiles, advertising, installment buying, and mass entertainment changed daily life, while agriculture and many workers faced persistent insecurity. The Harlem Renaissance expressed Black artistic achievement and debate. Nativist immigration quotas, the revived Ku Klux Klan, Prohibition, and conflicts over religion and science revealed struggles over national identity. Women's suffrage expanded formal participation through the Nineteenth Amendment, but racial barriers continued to prevent many women from voting. Interpret the decade through simultaneous cultural experimentation and organized exclusion.`,
`Worked continuity and change: Compare wartime demands for unity with the 1920s immigration quota system. Both could define belonging narrowly and target perceived outsiders, but one operated through wartime dissent controls and the other through immigration law. Explain the different mechanism rather than calling them identical. Balance evidence of consumer opportunity with unequal access to prosperity. Rising automobile ownership does not establish that agricultural debt, racial discrimination, or economic instability had disappeared.`,
`Do not confuse Black migration within the United States with international immigration. The Nineteenth Amendment did not remove every racial voting barrier, and rejection of the League did not end U.S. participation in world affairs.`,
`Check: How could the Great Migration change politics? Answer: Relocation to northern cities altered population patterns and increased opportunities for Black electoral organization where voting barriers differed, while creating new struggles over housing, jobs, and discrimination.`,
[['Great Migration','Large-scale movement of Black Americans from the South to other U.S. regions, driven by opportunity and escape from racial oppression.'],['Red Scare','A period of intense fear of radicalism and revolution, associated after World War I with repression and suspicion of immigrants and labor activists.'],['Harlem Renaissance','A flourishing of Black literature, art, music, and intellectual debate during the early twentieth century.'],['Nineteenth Amendment','The 1920 amendment prohibiting denial of voting rights on account of sex, without removing other discriminatory voting barriers.']]);
chapter(7,3,'Depression, New Deal, and World War II',
`The Great Depression emerged from interacting weaknesses, including financial instability, unequal purchasing power, fragile international debts, and contractions in production and credit. The 1929 crash was a major event, not a complete explanation. Bank failures and unemployment intensified the downturn, while the Dust Bowl combined drought with land-use practices to devastate parts of the Plains.

Franklin Roosevelt's New Deal expanded federal responsibility through relief, recovery, and reform. Banking measures sought to restore confidence, the Social Security Act established important protections, and the Wagner Act strengthened collective bargaining rights. Programs differed in purpose and effectiveness, and exclusions often disadvantaged agricultural and domestic workers, disproportionately affecting Black workers and women. Critics attacked the New Deal from both the right and the left. It transformed expectations of government without ending every inequality or fully restoring employment before wartime mobilization.

World War II drew the United States into vast military production after gradual involvement and the attack on Pearl Harbor. Women entered industrial jobs in larger numbers, and the Double V campaign connected victory abroad with victory over racism at home. Executive Order 8802 opposed discrimination in defense employment, but implementation remained contested.

At the same time, the federal government forcibly removed and incarcerated Japanese Americans, including U.S. citizens, on the West Coast. Korematsu v. United States upheld the exclusion policy in 1944; the policy demonstrates wartime failures to protect civil liberties. Allied victory and the use of atomic bombs reshaped global power. Wartime production ended the Depression's mass unemployment, while debates over state power, citizenship, and discrimination continued beyond victory.`,
`Worked evaluation: Compare New Deal labor protections with their exclusions. The Wagner Act strengthened many industrial workers' ability to organize, yet excluded categories limited its reach. Use a specific law and affected group rather than saying the New Deal helped everyone or did nothing. Apply the same method to wartime opportunity: industrial jobs expanded while incarceration and discrimination restricted rights. A strong argument identifies which institution changed, who benefited, and which barriers persisted.`,
`Do not attribute the Depression solely to the stock crash or say the New Deal immediately ended it. Use incarceration rather than implying Japanese Americans freely relocated, and distinguish exclusion from a finding of individual wrongdoing.`,
`Check: Why is the Double V campaign evidence of a connection between foreign and domestic issues? Answer: It used the struggle against fascism to press claims against racial discrimination at home, exposing contradictions in democratic war aims.`,
[['New Deal','Roosevelt-era programs expanding federal relief, recovery, and reform during the Great Depression.'],['Social Security Act','A 1935 law establishing federal old-age insurance and other social protections, initially leaving important categories of workers outside coverage.'],['Wagner Act','The 1935 National Labor Relations Act protecting collective bargaining for covered workers and establishing enforcement machinery.'],['Double V campaign','A wartime campaign linking victory over fascism overseas with victory over racism within the United States.']]);
chapter(8,1,'Cold War, Containment, and Decolonization',
`After World War II, tensions between the United States and Soviet Union developed through ideological differences, security fears, wartime experiences, and disputes over Europe's future. Containment sought to limit the expansion of Soviet influence rather than promise to reverse communism everywhere immediately. The Truman Doctrine connected U.S. aid to resistance against perceived communist pressure, while the Marshall Plan supported European recovery and strengthened economic and political ties.

NATO established a military alliance, and nuclear weapons transformed calculations about conflict. The Korean War showed how containment could produce a major conventional war without direct U.S.-Soviet battle. The conflict ended in an armistice rather than a peace treaty that reunited Korea. Military and economic commitments increased presidential power and sustained a large national security establishment.

Decolonization complicated the superpower rivalry. Movements in Asia, Africa, and elsewhere pursued their own goals; they were not simply instruments of Washington or Moscow. U.S. policymakers often interpreted local conflicts primarily through containment, contributing to interventions that could undermine democratic claims. The Vietnam War exposed this tension and provoked a growing domestic antiwar movement.

At home, loyalty investigations and McCarthyism associated dissent with disloyalty and restricted political debate. Some espionage concerns had a factual basis, but accusations often lacked evidence and damaged careers and liberties. The Cold War also encouraged investments in science, education, and infrastructure. Analyze policy through both perceived threats and consequences: explaining why officials feared Soviet expansion does not require assuming every intervention was justified or that local populations shared U.S. priorities.`,
`Worked comparison: The Marshall Plan and the Korean War both supported containment, but one relied chiefly on economic reconstruction and the other on military force. Connect each instrument to a specific setting. For Vietnam, distinguish Vietnamese nationalism and colonial history from the U.S. framing of communist expansion. A stronger causal explanation recognizes overlapping local and global conflicts rather than reducing every event to an order from one superpower. This also helps explain the limits of American power.`,
`Containment was not identical to rollback, and decolonization movements were not all communist. Do not describe the Korean armistice as reunification or assume an accusation during the Red Scare establishes guilt.`,
`Check: How could Cold War policy create tension with democratic ideals? Answer: U.S. support for anticommunist allies could include authoritarian governments, producing a conflict between strategic goals and stated commitments to self-government and liberty.`,
[['Containment','A strategy seeking to limit expansion of Soviet or communist influence through political, economic, and military measures.'],['Marshall Plan','U.S. assistance supporting European economic recovery after World War II, also strengthening ties against communist influence.'],['NATO','A collective-defense alliance formed in 1949 linking the United States, Canada, and several European states.'],['McCarthyism','Accusation-driven anticommunist politics associated with intimidation and inadequate evidence, named after Senator Joseph McCarthy.']]);
chapter(8,2,'Civil Rights and Expanding Rights Movements',
`The modern civil rights movement built on longstanding Black organizing, legal challenges, religious institutions, labor activism, and wartime demands for equality. Brown v. Board of Education in 1954 rejected segregated public schooling as inherently unequal, but implementation met organized resistance. Court decisions mattered, yet they required political pressure and enforcement to change institutions.

The Montgomery bus boycott, student sit-ins, Freedom Rides, voter registration campaigns, and mass demonstrations challenged segregation through different forms of direct action. Participants faced violence, imprisonment, and economic retaliation. Federal officials responded unevenly, balancing movement pressure, electoral calculations, constitutional responsibilities, and Cold War concerns about national reputation.

The Civil Rights Act of 1964 prohibited major forms of discrimination in public accommodations and employment. The Voting Rights Act of 1965 attacked mechanisms of racial disfranchisement and established federal enforcement. These laws transformed the legal framework, but de facto segregation, housing discrimination, unequal schooling, and economic inequality persisted. Black Power advocates emphasized self-determination, community control, and pride, with substantial diversity within the movement.

Other movements pursued related but distinct goals. Chicano activism challenged discrimination and labor exploitation; Indigenous activists demanded sovereignty and treaty rights; second-wave feminists targeted inequality in workplaces, education, and family life; gay rights activism gained visibility, including after Stonewall. These movements sometimes cooperated and sometimes disagreed over strategy, race, class, gender, and sexuality. Avoid treating them as copies of one model. Connect legal changes to organized pressure and distinguish formal equality from the power and resources required to exercise rights in practice.`,
`Worked causation: To explain the Voting Rights Act, connect local organizing and violent suppression of voting-rights protests to national attention and federal legislation. Naming a president alone misses the process that made action politically urgent. Compare Brown: litigation changed constitutional doctrine, while direct action challenged daily practices and enforcement failures. A defensible argument can identify complementary strategies without claiming that all activists endorsed the same goals or that legislative success ended the struggle.`,
`Brown addressed public schools, not every form of segregation by itself. Do not assume nonviolent protesters faced nonviolent opponents or that Black Power described a single organization. Distinguish tribal sovereignty claims from demands for individual assimilation.`,
`Check: Why might legal desegregation fail to produce equal schooling immediately? Answer: Residential patterns, resource disparities, resistance, and weak implementation could sustain unequal conditions despite a change in constitutional doctrine.`,
[['Brown v. Board of Education','The 1954 ruling rejecting racial segregation in public schools as inherently unequal.'],['Civil Rights Act of 1964','A federal law prohibiting major forms of discrimination in public accommodations and employment and expanding enforcement.'],['Voting Rights Act of 1965','A federal law targeting racial disfranchisement through stronger oversight and enforcement mechanisms.'],['Black Power','Diverse approaches emphasizing Black self-determination, community power, and pride, rather than one uniform organization or program.']]);
chapter(8,3,'Affluence, Great Society, and Political Distrust',
`Postwar economic growth expanded consumption, suburban development, higher education, and homeownership for many Americans. The GI Bill supported education and other benefits for veterans, while federal housing policies and highways encouraged suburbanization. Access was unequal: discrimination in lending, housing markets, and administration limited opportunities for many Black veterans and other excluded groups. Public policy helped create private prosperity rather than merely responding to it.

Suburban growth changed metropolitan geography, family life, and politics. Manufacturers and households moved outward, while many central cities faced changing tax bases and employment patterns. Popular ideals of domesticity emphasized a male breadwinner and female homemaker, but many women worked for pay, and family experiences differed by race and class. Television and consumer advertising promoted images that did not describe every household.

Lyndon Johnson's Great Society sought to address poverty, health care, education, and civil rights. Medicare and Medicaid expanded public involvement in health coverage, and antipoverty programs reflected a belief that federal action could improve opportunity. Critics disputed costs, federal authority, effectiveness, and the meaning of dependency. The Vietnam War consumed resources and undermined support for Johnson.

By the 1970s, inflation, energy shocks, deindustrialization, and unemployment challenged postwar economic assumptions. Watergate and revelations of government misconduct deepened distrust, while environmental activism and movements for consumer protection generated new regulation. These changes did not produce a single political response: liberals, conservatives, activists, and ordinary voters drew different lessons. Analyze the erosion of confidence as a process involving policy outcomes, economic conditions, and institutional behavior rather than a sudden universal rejection of government.`,
`Worked continuity and change: Compare New Deal and Great Society programs. Both expanded federal responsibility, but the Great Society developed during relative affluence and included health coverage and efforts against persistent poverty. Identify a specific program rather than treating the labels as interchangeable. Then qualify the narrative of progress with unequal housing access and later economic disruption. Prosperity can be real at the national level while its distribution remains unequal and politically contested.`,
`The GI Bill did not distribute benefits equally in practice. Medicare and Medicaid serve different populations and are not interchangeable. Do not explain the 1970s economy through one president or assume suburbanization occurred without public support.`,
`Check: Why does discriminatory mortgage access matter beyond the immediate purchase? Answer: Homeownership can generate equity across generations, so unequal access influences long-term wealth, school access, neighborhood resources, and political opportunity.`,
[['GI Bill','Federal veterans’ benefits supporting education and other opportunities after World War II, administered within systems that often discriminated.'],['Suburbanization','Growth of communities outside central cities, supported by transportation, housing policy, investment, and migration.'],['Great Society','Johnson-era initiatives addressing poverty, health, education, and civil rights through expanded federal action.'],['Stagflation','The combination of high inflation and weak economic growth or unemployment that challenged policymakers during the 1970s.']]);
chapter(9,1,'Conservative Resurgence and Economic Change',
`Conservatism gained strength through coalitions that criticized taxation, regulation, social change, and the expansion of federal programs. The movement drew on older anticommunism and free-market arguments as well as backlash against aspects of the 1960s and 1970s. Religious conservatives organized around issues including abortion, schooling, and family values. Business interests, suburban voters, and activists did not always share the same priorities, but coalition building helped produce electoral victories.

Ronald Reagan advocated lower taxes, deregulation, and stronger national defense. Supply-side arguments maintained that reducing tax burdens could encourage investment and production. Supporters credited these policies with renewed growth, while critics emphasized rising deficits, inequality, and weakened protections. Economic outcomes reflected multiple factors, including Federal Reserve policy and international conditions; they cannot be attributed to one tax law alone.

Deindustrialization and global competition changed employment patterns. Manufacturing jobs declined in many older industrial regions while service and technology sectors expanded. Sun Belt growth reflected climate, defense investment, migration, infrastructure, and business conditions. These changes redistributed political influence without producing uniform prosperity. Union decline altered workers' bargaining power, and the 1981 air traffic controllers' strike became a significant confrontation over public-sector labor.

The conservative resurgence did not simply eliminate the federal government. Defense spending increased, major entitlement programs persisted, and policy disputes concerned which activities government should support. The end of the Cold War resulted from Soviet internal problems, reform, movements in Eastern Europe, and international pressures as well as U.S. policy. A strong explanation distinguishes a leader's public claims from the broader forces shaping economic and geopolitical change.`,
`Worked evaluation: Evaluate the claim that Reagan reduced government. Specify taxation and regulation as areas of retrenchment, then qualify with defense expansion and continued entitlement spending. This produces an argument about changing priorities rather than a misleading yes-or-no answer. For economic outcomes, compare policy goals with evidence on growth, deficits, and distribution. A policy may coincide with recovery without being its only cause, and aggregate growth does not establish equal gains for every worker or region.`,
`Do not equate conservatism with the disappearance of federal spending or credit one country alone with ending the Cold War. Distinguish deindustrialization in particular regions from the disappearance of all U.S. manufacturing.`,
`Check: Why did Sun Belt growth matter politically? Answer: Population movement and expanding economic activity shifted congressional representation, electoral influence, and priorities toward growing southern and western states.`,
[['New Right','A conservative coalition combining economic, social, and foreign-policy priorities that gained influence in late-twentieth-century politics.'],['Supply-side economics','An approach emphasizing incentives for production and investment, often through lower taxation and reduced regulation.'],['Deindustrialization','A decline or restructuring of manufacturing employment and production in particular regions, with major effects on workers and communities.'],['Sun Belt','A broad southern and western region whose population and economic growth increased its political influence.']]);
chapter(9,2,'Globalization, Immigration, and Digital Transformation',
`Late-twentieth-century globalization intensified connections among production, finance, migration, and consumption. Trade agreements and new technologies allowed firms to coordinate activity across borders more easily. NAFTA reduced many trade barriers among the United States, Canada, and Mexico. Supporters emphasized markets and efficiency; critics emphasized employment losses, labor standards, environmental consequences, and unequal bargaining power. A balanced analysis distinguishes overall trade growth from the effects on particular workers and places.

Digital technology changed communication, work, commerce, and access to information. Personal computers, the internet, and later mobile networks created new industries and business models. They also raised questions about privacy, market concentration, unequal access, and the reliability of public information. Technological adoption depended on institutions, investment, and policy, not simply on inventions spreading automatically.

Immigration after the 1965 reform changed the origins and composition of the U.S. population. Newcomers from Latin America and Asia, alongside other regions, contributed to labor, entrepreneurship, culture, and community life. Migration reflected family networks, economic opportunities, political upheaval, and other pressures. Legal status and policy debates shaped people's experiences differently. Avoid assuming a single immigrant story or conflating lawful immigration, refugee status, and unauthorized migration.

Demographic and cultural changes generated both pluralism and political conflict. Movements challenged discrimination and sought recognition while opponents debated national identity and the role of government. Economic restructuring intersected with race, gender, geography, and education. Continuity-and-change analysis should identify an older pattern, such as nativism or industrial displacement, and explain how new technologies and global institutions altered its form rather than claiming recent changes had no historical precedent.`,
`Worked comparison: Compare late-nineteenth-century industrial change with globalization after 1980. Both created new opportunities while disrupting established work, but modern supply chains and digital coordination expanded the scale and speed of cross-border production. Use a specific mechanism rather than the vague statement that technology changed life. Immigration offers a second comparison: recurring arguments about belonging continued, while laws and migrants' origins changed. Similar rhetoric does not mean identical legal circumstances or outcomes.`,
`NAFTA did not create all globalization or eliminate every trade rule. Do not equate national income gains with equal worker gains, assume all immigrants share one legal status, or treat internet access as automatically equal political influence.`,
`Check: How can cheaper consumer goods coexist with local economic distress? Answer: International production may lower prices while reducing employment in a particular industry or town; benefits and costs can be distributed among different people and places.`,
[['Globalization','Increasing cross-border connections in production, finance, communication, migration, and culture, producing uneven benefits and costs.'],['NAFTA','A North American trade agreement implemented in 1994 that reduced many barriers among the United States, Canada, and Mexico.'],['Digital divide','Unequal access to digital technologies, reliable connectivity, and the skills needed to use them effectively.'],['Immigration and Nationality Act of 1965','A law ending the national-origins quota system and reshaping immigration through new preferences and limits.']]);
chapter(9,3,'Security, Rights, and Historical Argument after 1980',
`After the Cold War, the United States remained a major global power while facing new disputes over intervention and international responsibility. The Persian Gulf War, conflicts in the Balkans, and other crises raised questions about alliances, humanitarian aims, national interest, and limits on military action. These debates continued older arguments about the nation's role abroad but developed without the same bipolar structure.

The attacks of September 11, 2001 transformed national security policy. The United States invaded Afghanistan and later Iraq, while federal agencies expanded intelligence coordination and surveillance. The USA PATRIOT Act increased investigative powers and generated disputes over privacy and civil liberties. The Iraq invasion involved claims about weapons of mass destruction that were not substantiated by subsequent searches, illustrating the importance of evaluating official justifications against later evidence.

Domestic debates also concerned federal power, inequality, health care, environmental policy, and rights. The financial crisis of 2008 exposed vulnerabilities in housing and financial markets, leading to emergency intervention and arguments over responsibility and regulation. Polarization reflected long-term party realignment, media changes, social movements, and unequal economic experiences rather than a single event. Recent developments should be assessed through documented evidence, not predictions presented as settled history.

Historical reasoning remains essential when analyzing contested recent issues. A claim needs a clear time frame, relevant evidence, and an explanation of causation, comparison, or continuity and change. Distinguish a policy's intention from its outcome and separate correlation from demonstrated influence. When evidence is incomplete or interpretations differ, acknowledge those limits. The course's endpoint does not require treating current partisan judgments as historical facts; it requires explaining how developments emerged from earlier institutions, conflicts, and choices.`,
`Worked continuity and change: Compare post-2001 surveillance debates with World War I restrictions on dissent. Both involved claims that national security justified expanded federal authority, but the technologies, targeted activities, legal mechanisms, and political contexts differed. Build the comparison around those specific features rather than calling the periods identical. For a recent crisis, distinguish a source written to secure immediate support from a later investigation evaluating results. Different purposes affect the evidence each source can provide.`,
`Do not treat government allegations as established facts or assume every intervention had the same objective. Avoid presentism: judging earlier choices only by later outcomes can obscure the information and alternatives available at the time.`,
`Check: Why should a historian compare a policy announcement with later investigative findings? Answer: The announcement reveals justification and intended audience, while later evidence can test factual claims and outcomes; neither source alone answers every historical question.`,
[['USA PATRIOT Act','A 2001 law expanding investigative and surveillance authorities, prompting debates over security and civil liberties.'],['Financial crisis of 2008','A major breakdown in financial and housing markets that produced recession and extensive government intervention.'],['Political polarization','Increasing separation of political positions and identities, shaped by institutions, realignment, media, and social conflict.'],['Presentism','Interpreting the past solely through present assumptions or later knowledge rather than reconstructing historical context.']]);
const mcq:any[]=[];
function ask(ci:number,question:string,right:string,wrong:string[],reason:string,rejections:string[]){const answer=mcq.length%4;const choices=[...wrong];choices.splice(answer,0,right);const explanations=[...rejections];explanations.splice(answer,0,reason);mcq.push({id:`apush-mcq-${String(mcq.length+1).padStart(3,'0')}`,domain:domain(chapters[ci].unit),difficulty:'Medium',format:'mcq',question,choices,answer,_rationale:reason,explanation:explanations.map((x,i)=>`“${choices[i]}”: ${x}`).join('\n'),lessonTitle:`${chapters[ci].unit}.${chapters[ci].number} ${chapters[ci].title}`});}
ask(0,'An archaeologist finds irrigation works and permanent agricultural settlements in the precontact Southwest. Which inference is best supported?','Local communities organized labor to adapt food production to limited water.',['All North American peoples shared the same agricultural system.','European colonists introduced settled agriculture to the region.','Farming prevented exchange with neighboring communities.'],'Irrigation connects environmental conditions to organized agricultural adaptation.',['One region cannot establish continental uniformity.','The settlements predate European colonization.','Agriculture could support, rather than prevent, trade.']);
ask(0,'Why is a comparison between precontact Pueblo communities and Northwest Coast communities more useful than describing a single Indigenous culture?','It reveals distinct economic adaptations alongside possible shared social features.',['It ranks societies by closeness to European institutions.','It proves geography alone determined every political decision.','It shows all Indigenous peoples lived in isolated villages.'],'Comparison can identify diversity without assuming one standard of development.',['European institutions are not a neutral measure of complexity.','Human choices and cultural institutions also mattered.','Extensive exchange networks contradict universal isolation.']);
ask(1,'Which development best illustrates an economic consequence of the Columbian Exchange?','American food crops contributed to population growth in parts of Afro-Eurasia.',['Parliament granted representation to all Atlantic colonies.','European states abandoned overseas commerce.','Every Indigenous nation immediately adopted European private property.'],'Transferred crops changed food supplies and supported demographic growth.',['Representation is not a biological exchange.','Atlantic commerce expanded rather than disappeared.','Adoption varied, and property institutions did not change uniformly.']);
ask(1,'A historian argues that epidemic disease weakened resistance to conquest. Which qualification most improves the argument?','Disease interacted with warfare, forced labor, and local political alliances.',['Disease guaranteed identical colonial outcomes everywhere.','European weapons played no role in conquest.','Indigenous survivors ceased political organization.'],'Multiple interacting causes explain regional differences and avoid biological determinism.',['Outcomes and timing differed substantially.','A qualification need not deny other military factors.','Surviving communities continued rebuilding and resisting.']);
ask(2,'A Spanish official describes tribute and labor demands as justified by duties to protect and Christianize Indigenous people. This argument most directly legitimizes which arrangement?','Encomienda',['Universal Indigenous representation in the Cortes','Abolition of colonial labor obligations','An equal commercial partnership among sovereign states'],'Encomienda linked claims to tribute and labor with proclaimed protective and religious obligations.',['The statement does not establish representative equality.','It justifies labor demands rather than abolishing them.','Coercive obligations contradict equal bargaining.']);
ask(2,'How should a historian use a missionary petition condemning colonial abuses?','As evidence of disputes within empire, while testing its claims against other sources.',['As proof every Spanish authority opposed colonization','As proof legal reforms always ended exploitation','As evidence Indigenous communities had no interests of their own'],'An internal critic reveals debate but does not represent every official or affected community.',['A critic cannot stand for all imperial officials.','Stated reform and actual enforcement differ.','Indigenous agency requires its own evidence.']);
ask(3,'A northern merchant sells provisions to Caribbean plantations while operating outside a plantation region. The transaction best demonstrates that','regional economies could differ while sharing profits connected to slavery.',['northern commerce was independent of enslaved labor.','every northern household owned a plantation.','Caribbean plantations produced solely for local subsistence.'],'Provisioning links regional specialization to a common Atlantic system.',['The transaction directly shows a connection.','Regional connection does not imply identical ownership.','Plantation export production generated demand for imported provisions.']);
ask(3,'Which comparison most accurately distinguishes indentured servitude from racial chattel slavery?','Servitude generally had a contractual end, while enslavement became hereditary and lifelong.',['Only servants experienced coercive conditions.','Enslaved workers could universally end service by changing employers.','Servitude automatically conferred equal political rights.'],'Different legal duration and inheritance distinguished the systems despite coercion in both.',['Enslaved people faced extreme coercion.','Changing employers did not provide legal escape from bondage.','A labor contract did not guarantee political equality.']);
ask(4,'What does the Pueblo Revolt most clearly challenge?','The assumption that European claims always meant secure local control.',['The existence of Spanish religious pressure','The presence of organized Indigenous resistance','The importance of labor demands in colonial conflict'],'A coordinated revolt temporarily expelled Spanish authorities from much of New Mexico.',['Religious coercion helped provoke resistance.','The revolt demonstrates organized resistance.','Labor demands were among its causes.']);
ask(4,'Colonial laws increasingly made enslaved status follow the mother. What was a major effect?','They strengthened hereditary bondage and slaveholders’ property claims.',['They created a fixed end date for every labor obligation.','They gave enslaved mothers equal control over contracts.','They eliminated racial distinctions in colonial law.'],'Maternal inheritance reproduced enslaved status across generations.',['Hereditary status worked against a fixed term.','The laws restricted rather than equalized control.','The changes hardened racial hierarchy.']);
ask(5,'Which comparison best relates Enlightenment ideas to the First Great Awakening?','They offered different grounds for questioning inherited authority.',['Both demanded immediate colonial independence as a uniform program.','Both rejected all religion.','Both eliminated religious differences among colonies.'],'Reason-based inquiry and revivalist conversion differed but could challenge established institutions.',['Their influence on independence was indirect and varied.','The Awakening was a religious movement.','Revivals often produced denominational divisions.']);
ask(5,'Why did stricter enforcement of existing trade laws create new conflict after a period of loose supervision?','Colonists had developed commercial practices and expectations that enforcement disrupted.',['No trade laws had existed before the change.','Colonial assemblies had always controlled Parliament.','Mercantilism required unrestricted colonial trade.'],'Changing enforcement could transform an old legal framework into an immediate grievance.',['The issue was enforcement of existing laws.','Assemblies did not govern Parliament.','Mercantilism favored regulation, not unrestricted commerce.']);
ask(6,'A colonial petition objects to parliamentary taxation while affirming loyalty to the king. It best supports which interpretation?','Many colonists initially sought constitutional rights within the empire.',['All resistance began with a settled demand for independence.','Colonists objected only because taxes were too expensive.','Parliament accepted that colonial assemblies alone governed the empire.'],'Loyalty and resistance could coexist before separation became the movement’s goal.',['The petition explicitly retains imperial loyalty.','Its constitutional concern exceeds tax size.','Parliament maintained its own sovereignty claims.']);
ask(6,'How did nonimportation campaigns expand resistance beyond officeholders?','They made household purchasing and production forms of political action.',['They gave all consumers the legal right to vote.','They ended colonial participation in every market.','They required British troops to organize protests.'],'Consumers and producers could pressure imperial commerce without holding office.',['Informal participation did not confer suffrage.','Targeted boycotts were not an end to all exchange.','Colonial organizations, not troops, directed the campaigns.']);
ask(7,'Which statement most accurately explains the political effect of the Three-Fifths Compromise?','It increased slaveholding states’ representation without enfranchising enslaved people.',['It granted enslaved residents three-fifths of a vote.','It abolished the international slave trade immediately.','It guaranteed equal representation to every adult.'],'The formula counted population for representation and taxation, not individual voting rights.',['No fractional ballot was conferred.','The trade provision was a separate compromise.','Voting remained restricted.']);
ask(7,'Federalists and Anti-Federalists both claimed to defend liberty. What most clearly distinguished their arguments?','They disagreed about whether the proposed national structure would protect liberty or threaten accountability.',['Only Federalists believed government needed any limits.','Anti-Federalists uniformly supported a hereditary monarch.','Both rejected adding constitutional protections for rights.'],'Their debate concerned institutional design and safeguards, not liberty versus its complete rejection.',['Anti-Federalists also demanded limits on authority.','Monarchy was not their common alternative.','Promises of a bill of rights helped secure ratification.']);
ask(8,'Which controversy most directly involved the scope of implied federal powers?','Hamilton’s proposal for a national bank',['The arrival of horses in North America','The creation of the Pueblo religious movement','The precontact growth of Cahokia'],'The bank debate concerned whether constitutional powers authorized a useful but unlisted institution.',['Biological exchange was not a constitutional dispute.','This involved Indigenous resistance to Spanish rule.','Cahokia long preceded the Constitution.']);
ask(8,'Why is the election of 1800 significant without being evidence of universal democracy?','Power passed between rival parties while many populations remained excluded from voting.',['It abolished all partisan opposition.','It established equal voting rights regardless of race and sex.','It ended federal pressure on Indigenous lands.'],'Institutional transfer and restricted participation could coexist.',['Party competition continued.','Suffrage remained limited.','Dispossession continued after the election.']);
ask(9,'Which causal sequence best links the cotton gin to the expansion of slavery?','Faster processing increased cotton profitability, encouraging plantation expansion and forced labor demand.',['Faster processing eliminated cotton exports and labor demand.','The invention automatically freed enslaved textile workers.','Mechanization made land and markets irrelevant.'],'The machine affected profits within a wider system of markets, land seizure, and coercion.',['Cotton production expanded.','It did not legally emancipate workers.','Land and markets remained essential conditions.']);
ask(9,'A Lowell worker earns wages but protests long hours and strict supervision. Which interpretation best fits?','Industrial employment could create income opportunities while limiting workers’ control of labor.',['Wage work guaranteed complete personal independence.','All industrial workers had the legal status of enslaved people.','Factory schedules reproduced farm work without change.'],'Wages and workplace dependence were simultaneous features of industrialization.',['Economic need and management rules limited independence.','The legal distinction from chattel slavery remained fundamental.','Factories imposed a different organization of time and production.']);
ask(10,'Which evidence most directly qualifies the claim that Jacksonian politics expanded democracy for everyone?','Federal support for forced Indigenous removal alongside expanded white male voting.',['Growth of party newspapers','Increased turnout among eligible white voters','Reduction of some property requirements'],'These developments show inclusion for one population accompanying dispossession of another.',['Newspapers can support mass participation but do not establish universal inclusion.','Eligible-voter turnout does not measure excluded groups.','Property-rule changes alone do not show equal access.']);
ask(10,'Jackson opposed the national bank but demanded enforcement against nullification. These positions suggest that','his policies distinguished among uses of federal power rather than rejecting it uniformly.',['he consistently supported every claim of state supremacy.','he abolished executive authority.','he accepted South Carolina’s power to invalidate tariffs.'],'The Bank War and nullification crisis reveal different judgments about legitimate national authority.',['His nullification response contradicts uniform state supremacy.','He used executive power vigorously.','He rejected unilateral nullification.']);
ask(11,'Which development best explains how reform work encouraged women’s rights activism?','Organizing developed public skills while exclusion within movements exposed unequal treatment.',['Reform instantly granted all women national voting rights.','Abolitionist groups uniformly supported equal female leadership.','Religious revivals prohibited all voluntary associations.'],'Experience and discrimination could combine to generate broader equality claims.',['National suffrage came much later.','Abolitionists disagreed about gender roles.','Revivals often encouraged organization.']);
ask(11,'What distinguishes immediate abolition from colonization proposals?','Immediate abolition demanded ending slavery without requiring removal of freedpeople abroad.',['Immediate abolition required all Black Americans to leave the country.','Colonization guaranteed equal citizenship within the United States.','Both movements agreed that slavery must remain indefinitely.'],'The movements differed on emancipation and the place of free Black people in the nation.',['Removal abroad characterized colonization proposals.','Colonization often denied the possibility of equality at home.','Abolition expressly demanded slavery’s end.']);
ask(12,'Why did the U.S.-Mexican War intensify sectional conflict?','New territories reopened disputes over slavery’s expansion and political power.',['The treaty permanently settled every slavery question.','Mexico required the United States to abolish slavery nationally.','Territorial expansion had no relationship to congressional representation.'],'Acquisition forced decisions about labor systems and the sectional balance.',['The debate grew more intense.','The treaty did not impose national abolition.','Potential new states could alter power in Congress.']);
ask(12,'Which outcome most directly undermined popular sovereignty as a peaceful solution to slavery in Kansas?','Rival governments and violence contested who could legitimately decide the territory’s future.',['Universal acceptance of a single fair election','Immediate national agreement to abolish slavery','The disappearance of competing settlers’ organizations'],'Conflict over participation and authority made the decision process itself a source of violence.',['The election process was disputed.','No such agreement followed.','Competing organizations mobilized intensely.']);
ask(13,'Which explanation best accounts for the expansion of Union war aims?','Enslaved people’s actions, military needs, political pressure, and executive decisions interacted.',['Emancipation was fully accomplished before fighting began.','The Proclamation applied equally to all loyal border states.','Black Americans had no influence on wartime policy.'],'Multiple actors and wartime conditions helped make emancipation central.',['Slavery continued when the war began.','The Proclamation had specific territorial limits.','Escape, service, and activism influenced events.']);
ask(13,'Which evidence most directly shows a legal change beyond the Emancipation Proclamation’s wartime limits?','Ratification of the Thirteenth Amendment',['The earlier purchase of Louisiana','The Articles of Confederation','The passage of the Stamp Act'],'The amendment established national constitutional abolition, subject to its punishment exception.',['Louisiana concerned territorial acquisition.','The Articles did not abolish slavery.','The Stamp Act was a colonial revenue measure.']);
ask(14,'What most directly explains the gap between Reconstruction amendments and actual voting access?','Violence and discriminatory administration obstructed rights that required enforcement.',['The amendments explicitly required universal literacy tests.','The Fifteenth Amendment enfranchised only former Confederates.','Ratification removed every need for federal action.'],'Rights on paper could be blocked when protective enforcement weakened.',['The amendments did not mandate such tests.','Its racial-discrimination prohibition was not limited to former Confederates.','Enforcement remained central.']);
ask(14,'Which thesis best evaluates Reconstruction?','It transformed constitutional citizenship while leaving land distribution and equal political power deeply contested.',['It changed no national legal principles.','It created permanent racial equality by 1877.','It erased all differences between slavery and free labor.'],'A qualified judgment distinguishes lasting legal changes from restricted implementation and material inequality.',['The amendments substantially changed constitutional law.','Violence and disfranchisement contradicted that claim.','Freedom and exploitative contracts remained legally different.']);
ask(15,'A steel company owns mines, transport lines, and mills. Which strategy does this illustrate?','Vertical integration',['Popular sovereignty','Horizontal integration alone','Nonimportation'],'The company controls successive stages of a production chain.',['That concerns territorial decisions about slavery.','Horizontal integration combines competitors at one stage.','Nonimportation is a boycott strategy.']);
ask(15,'Federal troops and court injunctions used during major strikes most directly demonstrate that','government decisions could strengthen employers’ position in labor conflict.',['government always remained neutral in industrial disputes.','all workers held equal political influence.','labor conflict ended once national markets developed.'],'State coercion and legal orders affected bargaining power and strike outcomes.',['Intervention contradicts neutrality.','The examples reveal unequal access to institutional power.','National markets generated continuing conflict.']);
ask(16,'Which result most clearly contradicts the Dawes Act’s presentation as a simple gift of secure land?','Allotment facilitated extensive transfers of reservation lands out of Indigenous control.',['It strengthened communal ownership everywhere.','It prohibited all non-Indigenous settlement.','It restored complete tribal independence.'],'Individual allotment and so-called surplus sales weakened collective landholding.',['Communal tenure was a target of the policy.','The policy opened land to outsiders.','Federal restrictions on sovereignty persisted.']);
ask(16,'Why is a description of the West as vacant land historically misleading?','It erases Indigenous societies, sovereignty, and existing uses of territory.',['It recognizes that migration involved conflict.','It distinguishes environmental conditions among regions.','It acknowledges federal investment in railroads.'],'Vacancy language obscures the peoples and institutions displaced by expansion.',['Acknowledging conflict corrects rather than creates the problem.','Regional differentiation is useful evidence.','Federal support is compatible with a nonvacant West.']);
ask(17,'Which comparison best explains support for political machines among some immigrants?','Machines supplied practical aid that inadequate public services often failed to provide.',['Machines guaranteed an end to all corruption.','Immigrants had no capacity for independent political choices.','Every machine opposed immigration.'],'Assistance and patronage helped build loyalty without making machines uniformly benevolent.',['Provision of aid did not remove corruption.','This stereotype fails to explain material incentives.','Many machines cultivated immigrant support.']);
ask(17,'Populist demands for railroad regulation and monetary expansion suggest that farmers','saw structural market and credit relationships as sources of hardship.',['sought to abolish all commercial farming.','believed debt problems could only be individual moral failings.','opposed every form of national political action.'],'Their platform challenged the organization of credit and transportation power.',['They generally wanted fairer market conditions.','Collective reforms challenged an exclusively individual explanation.','They organized a national party.']);
ask(18,'Which evidence best complicates a claim that Progressive reform always expanded equality?','Economic regulation expanded while federal workplace segregation intensified.',['Food-safety legislation addressed industrial abuses.','Some states adopted direct democratic reforms.','Women organized suffrage campaigns.'],'Reform and racial exclusion could coexist within the same administration.',['Food regulation supports reform but does not expose its exclusions.','Electoral reforms alone do not measure racial equality.','Suffrage organizing shows activism rather than universal reform results.']);
ask(18,'Filipino resistance to U.S. annexation most directly challenges which justification of empire?','The claim that American rule simply fulfilled colonized people’s desire for freedom.',['The claim that overseas territories raised constitutional questions','The observation that military force supported expansion','The existence of domestic opposition to imperialism'],'Resistance demonstrates that U.S. control conflicted with many Filipinos’ independence goals.',['Annexation did raise constitutional questions.','The fighting confirms the use of force.','Anti-imperialists existed regardless of Filipino resistance.']);
ask(19,'A Black family leaves Mississippi for an industrial city during World War I. Which combination best contextualizes the move?','Employment opportunities and efforts to escape Jim Crow oppression.',['A universal end to northern discrimination and southern poverty','The complete closure of northern factories','A federal law requiring all Black families to migrate'],'The Great Migration reflected both economic opportunity and racial coercion in the South.',['Discrimination and poverty did not disappear.','Industrial demand attracted workers.','The migration was not a universal federal relocation order.']);
ask(19,'Which interpretation best accounts for consumer growth alongside immigration quotas in the 1920s?','Economic and cultural change coexisted with organized efforts to restrict national belonging.',['Consumer prosperity eliminated nativism.','Quotas granted all nationalities identical unrestricted access.','Cultural conflict meant no technological changes occurred.'],'The decade combined experimentation, growth, exclusion, and unequal access.',['Nativism persisted and intensified.','The quota system discriminated by national origins.','Social conflict did not prevent technological innovation.']);
ask(20,'Which statement best distinguishes explanation of the Great Depression from identification of a single event?','The crash interacted with banking instability, weak demand, and international financial problems.',['The crash alone fully explains every stage of the downturn.','The Depression began because Social Security already covered all workers.','The Dust Bowl occurred independently of environmental practices.'],'A multi-causal account explains transmission and persistence of economic collapse.',['A single trigger does not explain the whole crisis.','Social Security was enacted after the downturn began.','Land use interacted with drought.']);
ask(20,'The Double V campaign and Japanese American incarceration together support which argument?','Democratic wartime ideals coexisted with struggles against racial discrimination and rights violations.',['Wartime mobilization ended every civil-rights conflict.','All Americans experienced identical legal treatment.','The federal government withdrew from domestic affairs during the war.'],'Claims to democracy highlighted contradictions between national ideals and discriminatory policies.',['The evidence demonstrates continuing conflict.','Incarceration shows unequal treatment.','Mobilization expanded federal activity.']);
ask(21,'How did the Marshall Plan differ from U.S. intervention in Korea while sharing a broader aim?','It emphasized economic reconstruction as an instrument of containment.',['It sought immediate military conquest of the Soviet Union.','It ended U.S. commitments outside the Western Hemisphere.','It rejected cooperation with European states.'],'Economic aid and military force were different containment tools.',['Containment did not necessarily mean rollback by invasion.','The program expanded overseas involvement.','European cooperation was fundamental.']);
ask(21,'Which approach best avoids reducing decolonization to superpower competition?','Examine local nationalist goals alongside U.S. and Soviet strategies.',['Assume every local movement followed Moscow’s instructions.','Ignore the legacies of European empires.','Treat all independence movements as identical to U.S. policy.'],'Local actors pursued distinct objectives within and beyond the Cold War framework.',['This erases local agency and diversity.','Colonial institutions shaped many conflicts.','Independent movements often opposed U.S. priorities.']);
ask(22,'Which explanation most effectively connects civil-rights organizing to federal law?','Local campaigns and reactions to repression created pressure that helped make legislation politically urgent.',['Federal laws emerged without prior activism.','Court rulings alone immediately changed every practice.','All activists agreed on a single strategy.'],'Organized pressure links movement agency to institutional change.',['Activism preceded and shaped legislation.','Implementation required continuing struggle.','Movements contained important strategic differences.']);
ask(22,'Indigenous activists emphasize treaty rights and tribal sovereignty. Why is describing this only as a demand for individual assimilation inadequate?','Their claims concern collective political authority as well as treatment of individuals.',['Treaties concern only personal consumer choices.','Sovereignty requires abandoning every Indigenous institution.','All rights movements sought identical legal arrangements.'],'Tribal sovereignty addresses a people’s governing authority and agreements with other governments.',['Treaties establish political relationships.','Assimilation could threaten rather than fulfill sovereignty.','Different histories produced distinct claims.']);
ask(23,'How could discriminatory access to postwar mortgages contribute to long-term inequality?','It restricted opportunities to accumulate housing equity and transmit wealth.',['It affected only a household’s choice of paint color.','It ensured identical school access in every neighborhood.','It prevented all suburban growth.'],'Housing access influences wealth, resources, and later opportunities.',['The effects extended beyond consumer preference.','Residential and school opportunities remained unequal.','Suburbs grew despite unequal access.']);
ask(23,'Which comparison most accurately relates the Great Society to the New Deal?','Both expanded federal responsibility, but they developed in different economic contexts and used distinct programs.',['Both began during the same administration.','Neither included public social protections.','The Great Society abolished all earlier federal programs.'],'Comparison requires identifying shared purposes and differences such as Medicare’s health coverage.',['The administrations and decades differed.','Both involved social protections.','Many earlier programs continued.']);
ask(24,'Which evidence most directly qualifies a claim that Reagan uniformly reduced the federal role?','Defense spending expanded while tax reduction and deregulation were pursued.',['He advocated lower taxes.','He criticized regulation.','Conservative groups criticized some social programs.'],'Government priorities shifted rather than all activities shrinking together.',['This states one dimension of retrenchment without qualifying it.','The criticism alone does not show the entire government’s size.','Opposition to programs does not establish their disappearance.']);
ask(24,'Why should a historian avoid attributing the end of the Cold War solely to U.S. military spending?','Soviet internal problems, reform, and movements in Eastern Europe also shaped the outcome.',['The United States had no role in international affairs.','All communist governments collapsed simultaneously for identical reasons.','Diplomacy and local political choices were irrelevant.'],'A multi-causal explanation includes forces within the Soviet bloc as well as external pressure.',['Rejecting a single cause does not deny U.S. influence.','Developments varied across states.','Reform and local mobilization were important.']);
ask(25,'Cheaper imported goods coincide with factory closures in a particular town. Which conclusion is most defensible?','Globalization’s benefits and costs may fall on different populations and places.',['National trade growth guarantees every worker gains.','Consumer prices prove no jobs can be lost.','Local losses prove international trade has no beneficiaries.'],'Distributional analysis distinguishes aggregate outcomes from regional experiences.',['Aggregate growth does not establish individual gains.','Prices and employment measure different effects.','Consumers and some producers may still benefit.']);
ask(25,'Which comparison best connects recent nativism with earlier immigration conflicts?','Debates over belonging recur, while migrants’ origins, laws, and political contexts change.',['The national-origins quota system remained legally unchanged after 1965.','All migration occurs for one economic reason.','Digital media makes historical comparison impossible.'],'Continuity-and-change analysis identifies recurring themes without erasing institutional differences.',['The 1965 law ended that quota structure.','Family, persecution, and other causes also matter.','New media changes the setting but does not prevent comparison.']);
ask(26,'Why should a historian compare a government justification for war with later investigative findings?','The sources answer different questions about purpose, evidence, and outcomes.',['Official announcements automatically establish every factual claim.','Later evidence always reveals what every official privately knew.','A source’s purpose has no relevance to interpretation.'],'Triangulating sources distinguishes public arguments from tested claims and subsequent results.',['Claims require evaluation rather than automatic acceptance.','Later findings do not establish every earlier private belief.','Purpose helps explain emphasis and omissions.']);
ask(26,'Which comparison between World War I and the post-September 11 era is most historically responsible?','Both involved security-based expansions of federal authority, but legal mechanisms and technologies differed.',['The two periods had identical institutions and targets.','National security had never influenced rights debates before 2001.','Historical context is unnecessary when policies appear similar.'],'A valid comparison identifies a shared relationship and specifies important differences.',['Similarity does not imply identity.','Earlier wars generated major civil-liberties conflicts.','Context prevents superficial equivalence.']);
// These stimulus/reasoning revisions target plausible historical misconceptions.
function revise(n:number,question:string,wrong:string[],rejections:string[]){const q=mcq[n-1],right=q.choices[q.answer],choices=[...wrong],reasons=[...rejections];choices.splice(q.answer,0,right);reasons.splice(q.answer,0,q._rationale);q.question=question;q.choices=choices;q.explanation=reasons.map((x,i)=>`“${choices[i]}”: ${x}`).join('\n');q.difficulty='Hard';}
revise(1,'Original archaeological scenario: Irrigation channels connect fields to a permanent settlement in the precontact Southwest. A historian compares this evidence with coastal fishing settlements. Which conclusion about the southwestern site is best supported?',
['Political cooperation emerged principally through trade with English colonies.','Agricultural settlement depended on the same resource base as Northwest Coast fishing communities.','Permanent settlement required abandonment of exchanges with neighboring groups.'],['The site predates English colonial networks.','The comparison shows different resource systems, not an identical base.','Local production and external exchange could coexist.']);
revise(4,'A historian links epidemic mortality to weakened resistance during conquest. Another notes that Europeans allied with Indigenous rivals of existing rulers. Which revision best incorporates both bodies of evidence?',
['Demographic losses mattered mainly because Europeans had already established secure rule.','Political alliances explain conquest more effectively when disease is excluded from the account.','Technological differences produced conquest independently of regional political relationships.'],['That reverses the proposed chronology and overlooks epidemics during conquest.','The accounts identify interacting causes, not mutually exclusive alternatives.','Alliances indicate the relevance of regional power struggles.']);
revise(7,'Original commercial scenario: A Boston merchant supplies preserved fish to a Caribbean sugar estate and reinvests the proceeds in shipping. Which interpretation best explains the regional relationship?',
['Different northern crops separated New England commerce from plantation labor systems.','The merchant’s profits show that northern shipping had replaced Caribbean agricultural exports.','This transaction demonstrates that New England and the Caribbean used equivalent labor institutions.'],['Provisioning tied northern commerce to plantation production despite different local crops.','Shipping supported the plantation export system rather than replacing it.','Economic interdependence does not establish identical labor regimes.']);
revise(10,'A historian traces seventeenth-century laws making a child’s enslaved status follow the mother. Which consequence most directly follows from that legal rule?',
['It preserved the temporary status characteristic of indentured contracts.','It shifted colonial labor law toward treating Christian baptism as a route to automatic release.','It gave enslaved households authority comparable to employers in negotiating children’s status.'],['Maternal inheritance reproduced bondage rather than setting a contractual end.','Baptism-based freedom is not the mechanism described by this rule.','The rule protected masters’ control, not equal household bargaining.']);
revise(13,'Original source scenario: In the mid-1760s, a colonial petition affirms royal loyalty but disputes Parliament’s power to impose internal taxes. What is the most defensible interpretation?',
['The petition applies the later Constitutional Convention’s division of federal and state powers.','Its authors seek lower prices while accepting Parliament’s unrestricted taxing authority.','Its authors have already committed their colony to a republican government outside the empire.'],['The 1787 constitutional structure is anachronistic here.','A dispute over authority is different from accepting that authority while negotiating price.','Expressed royal loyalty supports a reform-within-empire interpretation.']);
revise(16,'A classroom pairs a Federalist argument that an extended republic can control faction with an Anti-Federalist warning about distant rulers. Which comparison best captures their disagreement?',
['Federalists trusted state governments while Anti-Federalists sought stronger national taxation.','Their central disagreement concerned whether slavery should be immediately abolished.','Anti-Federalists opposed representation itself, whereas Federalists rejected constitutional limits.'],['This reverses their typical concerns over national power.','Slavery mattered at the convention, but these paired claims concern institutional accountability.','Both operated within a republican debate over representative institutions and limits.']);
revise(19,'Original economic scenario: Cotton processing becomes faster while textile demand rises and settlers gain access to new southern lands. Which explanation best links these developments to labor conditions?',
['Processing gains made the plantation system less dependent on coerced labor by reducing total cotton output.','Textile demand encouraged southern planters to replace cotton with subsistence crops.','Technological change expanded profits without affecting decisions about land acquisition or labor.'],['Lower processing costs encouraged expansion rather than reduced output.','The demand increased incentives to grow cotton.','Profit incentives shaped expansion and slaveholders’ labor demands.']);
revise(22,'Jackson denounced the national bank as a privileged institution but rejected South Carolina’s nullification claim. Which interpretation best reconciles these positions?',
['He treated constitutional limits as requiring the president to defer to state challenges in each case.','His administration preferred congressional control over executive intervention in both disputes.','The bank controversy and nullification crisis both centered chiefly on admission of western states.'],['His enforcement stance rejected South Carolina’s claimed power.','He employed executive authority in both disputes.','The disputes concerned finance and tariff authority, not chiefly state admission.']);
revise(25,'Original historical argument: The acquisition of Mexican territory altered the stakes of congressional debate in the late 1840s. Which explanation best accounts for that change?',
['The treaty resolved the balance of power by requiring the territory to enter as a single slave state.','The central dispute concerned whether existing southern states could be required to adopt industrial wage labor.','Territorial acquisition displaced slavery with disagreements limited chiefly to diplomatic recognition of Mexico.'],['The treaty did not settle territorial slavery or state admission in that way.','The immediate dispute concerned slavery’s expansion, not compulsory southern industrialization.','Slavery and its political implications remained central.']);
revise(28,'The Emancipation Proclamation applied to designated areas in rebellion rather than all slaveholding jurisdictions. Which later development most directly changed abolition’s national legal scope?',
['The Fourteenth Amendment’s equal-protection clause','The Freedmen’s Bureau’s establishment of schools','The Fifteenth Amendment’s protection against racial voting discrimination'],['The Fourteenth concerns citizenship and protections, not the amendment that nationally abolished slavery.','Education supported freedom but did not itself create constitutional abolition.','Voting protection is distinct from abolition.']);
revise(31,'Original business scenario: A steel producer acquires ore mines, freight facilities, and finishing mills. Which strategy best describes the organization?',
['A trust strategy limited to consolidating competing finished-steel producers','A craft-union strategy aimed at controlling apprenticeship','A monetary expansion program designed to relieve farm debt'],['Buying same-stage competitors is horizontal integration; the scenario spans production stages.','The owner is reorganizing the corporation, not skilled labor membership.','Currency reform does not describe ownership across production stages.']);
revise(34,'An official praises allotment for turning Indigenous families into individual landowners. Which evidence would most directly qualify that favorable assessment?',
['The policy expanded the area governed through communal landholding.','The law placed reservation sovereignty beyond future federal intervention.','Allotment shifted control of land to tribal councils rather than individual households.'],['The policy divided communal holdings rather than expanding them.','Federal intervention continued, and sovereignty remained restricted.','The policy emphasized individual holdings and facilitated outside acquisition.']);
revise(37,'A historian describes Progressive economic regulation as a broad advance toward equality. Which evidence most directly requires the historian to qualify that conclusion?',
['Antitrust policy sometimes distinguished acceptable large firms from abusive combinations.','The establishment of the Federal Reserve expanded financial administration.','Food-safety campaigns increased the federal role in consumer protection.'],['This qualifies how regulation operated but does not directly show the racial inequality highlighted by the correct evidence.','An institutional expansion alone does not establish the exclusion at issue.','Consumer protection illustrates reform, whereas federal segregation directly contradicts universal equality.']);
revise(40,'A historian pairs automobile advertising with the national-origins quota laws of the 1920s. What interpretation best connects the two without collapsing them into one development?',
['New consumer practices displaced conflicts about national identity with agreement over immigration.','Quota laws expanded immigration in direct proportion to demand for factory labor.','Rising consumption shows that economic opportunities were distributed evenly across ethnic groups.'],['Nativist restrictions demonstrate continuing conflict rather than displacement by consensus.','The quotas imposed discriminatory limits rather than matching industrial labor demand.','Consumption growth does not prove equal access to opportunity.']);
revise(43,'The United States financed European reconstruction and later fought in Korea. Which explanation best distinguishes the Marshall Plan while connecting it to a shared policy framework?',
['It used economic resources primarily to dissolve NATO’s collective-defense obligations.','It transferred security policy chiefly to the League of Nations.','It used aid to promise immediate overthrow of communist governments throughout Eastern Europe.'],['The plan supported recovery and Western ties; it did not dissolve NATO commitments.','The League was not the governing institution of postwar containment.','Containment and immediate rollback were different objectives.']);
revise(46,'Indigenous activists demand treaty enforcement and authority over reservation affairs. Why is interpreting these demands solely through individual civil-rights assimilation misleading?',
['Treaty enforcement concerns cultural recognition but excludes governing authority.','Individual citizenship necessarily eliminates the possibility of collective political claims.','Demands for federal recognition mean activists seek replacement of tribal governments by state governments.'],['Treaties and reservation jurisdiction concern political authority as well as culture.','Individual citizenship can coexist with collective sovereignty claims.','Recognition does not imply a demand to dissolve tribal government into state control.']);
revise(49,'A historian evaluates Reagan’s promise to reduce government. Which evidence most directly supports a thesis about changing federal priorities rather than uniform withdrawal?',
['Income-tax reductions accompanied a decline in federal responsibility for national defense.','Deregulation transferred Social Security entirely to state governments.','Criticism of federal programs meant that Congress had ended major entitlement spending.'],['Defense expansion, not withdrawal, qualifies the reduction claim.','Social Security remained a federal program.','Political criticism did not establish termination of major entitlements.']);
revise(52,'A historian compares immigration conflicts in the 1890s and after 1980. Which approach best establishes continuity while preserving historical differences?',
['Treat contemporary immigration law as a continuation of the unchanged national-origins quota system.','Explain both periods entirely through factory demand, setting aside family and political migration.','Use recurring nativist rhetoric as proof that migrants faced identical legal classifications.'],['The 1965 law changed the national-origins system.','Migration has multiple causes and different institutional contexts.','Similar arguments about belonging do not imply identical laws or statuses.']);
mcq.forEach(q=>{delete q._rationale;});
const sourceUrls={declaration:'https://www.archives.gov/founding-docs/declaration-transcript',articles:'https://www.archives.gov/milestone-documents/articles-of-confederation',constitution:'https://www.archives.gov/founding-docs/constitution-transcript',removal:'https://guides.loc.gov/indian-removal-act/digital-collections',emancipation:'https://www.archives.gov/milestone-documents/emancipation-proclamation',amendment14:'https://www.archives.gov/milestone-documents/14th-amendment',plessy:'https://www.archives.gov/milestone-documents/plessy-v-ferguson',eo9066:'https://www.archives.gov/milestone-documents/executive-order-9066',civilRights:'https://www.archives.gov/milestone-documents/civil-rights-act'};
const frq:any[]=[];
const criterion=(key:string,label:string,points:number,prompt:string,guidance:string)=>({key,label,points,prompt,guidance});
function written(unit:number,set:number,slot:number,type:string,title:string,question:string,criteria:any[],explanation:string){frq.push({id:`apush-frq-set${set}-${slot}`,domain:domain(unit),difficulty:'Hard',format:'frq',set,setName:set===1?'Power, Expansion, and Citizenship':'Work, Equality, and the Federal State',frqType:type,title,maxPoints:criteria.reduce((n,c)=>n+c.points,0),question:`${title}\nOriginal AscendSAT skill practice — Set ${set}, Task ${slot}. These four-task sets are not replicas of an official exam section.\n\n${question}`,criteria,rubric:criteria.map(c=>`${c.label} (${c.points} point${c.points===1?'':'s'}): ${c.guidance}`).join('\n\n'),explanation:`Unofficial, original practice. The criteria are app-authored and do not predict an official AP score. ${explanation}`});}
written(3,1,1,'short_answer','SAQ: Revolutionary Principles and Their Limits',
`Source: The Continental Congress, Declaration of Independence, 1776. The following is an instructional paraphrase, not a quotation: Legitimate government protects inherent rights and rests on the consent of the governed; people may alter a government that persistently violates those purposes. Full primary text: ${sourceUrls.declaration}\n\nA. Identify ONE political principle expressed in this source.\nB. Explain ONE imperial development between 1763 and 1776 that helps explain the source's argument.\nC. Explain ONE example between 1776 and 1800 showing a limit to the application of the principle you identified.`,[
criterion('A','Part A',1,'Identify one political principle.','Award 1 for accurately identifying natural rights, consent of the governed, or a right to change an abusive government. Do not require any particular phrase; merely naming democracy without explaining its meaning is insufficient.'),
criterion('B','Part B',1,'Explain a relevant imperial development.','Award 1 for a specific development, such as the Stamp Act, Coercive Acts, or conflict over parliamentary representation, connected to colonists’ claims about rights or consent. A named event without a connection earns 0.'),
criterion('C','Part C',1,'Explain a limit within 1776–1800.','Award 1 for specific evidence such as continued enslavement, restricted female suffrage, or Indigenous dispossession, explaining whose consent or rights were excluded. Do not require the student to argue that the Declaration itself created the restriction.')],
`Model reasoning: The Stamp Act dispute concerned legitimate authority, not simply tax size. Continued slavery then demonstrates the gap between universal language and actual institutions. Accept other historically accurate evidence within the specified periods.`);
written(5,1,2,'short_answer','SAQ: A Reconstruction Timeline',
`Source: AscendSAT's original secondary timeline, summarizing U.S. constitutional amendments. This is a non-text schematic, not an official exam image or a claim that laws were fully enforced. Primary texts: https://www.archives.gov/founding-docs/amendments-11-27\n\n1865 → Thirteenth Amendment: abolition of slavery, with a punishment-after-conviction exception.\n1868 → Fourteenth Amendment: national citizenship and legal protections.\n1870 → Fifteenth Amendment: racial discrimination in voting prohibited.\n\nA. Describe ONE change in federal responsibilities suggested by the timeline.\nB. Explain ONE action by freedpeople or their allies that sought to make these changes meaningful.\nC. Explain ONE development between 1865 and 1898 that limited their practical effect.`,[
criterion('A','Part A',1,'Describe a change in federal responsibilities.','Award 1 for describing national constitutional protection of freedom, citizenship, or voting against discriminatory state action. Merely repeating a date does not describe a change.'),
criterion('B','Part B',1,'Explain action to implement freedom or rights.','Award 1 for an accurate example such as establishing schools, political organizing, voting, officeholding, pursuing family reunification, or demanding land, connected to exercising freedom or citizenship.'),
criterion('C','Part C',1,'Explain a restriction on implementation.','Award 1 for explaining how a specific development such as Klan terrorism, discriminatory voting administration, withdrawal of federal protection, or segregation restricted rights. An answer claiming the amendments were repealed earns no point for that claim.')],
`The timeline depicts formal constitutional change. Strong answers distinguish constitutional protections from their implementation and connect freedpeople's own organizing to the struggle over citizenship.`);
const leqCriteria=(evidenceGuidance:string)=>[
criterion('thesis','Thesis or claim',1,'Develop a defensible thesis responding to the prompt.','Award 1 for a historically defensible claim that establishes a line of reasoning. Restating the question or listing topics without a position earns 0.'),
criterion('context','Historical context',1,'Explain a broader historical setting relevant to the argument.','Award 1 for describing a broader development and connecting it to the argument. A date, name, or unexplained phrase alone is insufficient.'),
criterion('evidence','Specific evidence',2,'Use at least two distinct pieces of specific evidence to support the argument.',`Award up to 2: 1 for at least two accurate, specific, relevant examples; 2 when at least two such examples are used to support the argument rather than merely listed. One accurate example alone does not meet this app criterion. ${evidenceGuidance}`),
criterion('reasoning','Historical reasoning',1,'Organize an explanation through causation, comparison, or continuity and change.','Award 1 for explaining a relationship that advances the thesis, rather than merely arranging events chronologically.'),
criterion('complexity','Qualified understanding',1,'Develop a meaningful qualification or explain interacting perspectives or causes.','Award 1 for a developed qualification supported by evidence, such as explaining unequal effects on distinct groups or an important counterexample. A token however sentence, unsupported assertion, or repeated thesis earns 0.')];
written(4,1,3,'long_essay','LEQ: Expansion and the Meaning of Democracy',
`From the founding era through Reconstruction, expansion affected political participation, economic opportunity, and the sovereignty of peoples already living in claimed territories. Develop an argument evaluating how expansion changed the meaning or practice of democracy in the United States between 1783 and 1877. You may focus on ONE or more developments and need not cover the entire period. Explain your chosen historical setting, use at least TWO specific pieces of evidence, and qualify your conclusion where warranted.\n\nThis is one required-style broad practice prompt, not a menu of legacy exam choices. The six-point app rubric practices historical argumentation; it is not an official scoring instrument.`,leqCriteria('Examples might include the Northwest Ordinance, removal, Texas annexation, the Kansas-Nebraska Act, or Reconstruction voting. Accept other accurate evidence; evaluate its use, not whether it appears on this list.'),
`A strong response can argue that expansion enlarged participation among some white settlers while intensifying Indigenous dispossession and conflict over enslaved people's rights. Other defensible theses are welcome. Do not demand coverage of every decade.`);
written(5,1,4,'mini_dbq','Mini-DBQ: National Power and Its Unequal Uses',
`Evaluate the extent to which federal power expanded between 1781 and 1865 and explain how its effects differed among populations. Use the FOUR documents below and at least ONE specific piece of outside evidence. These short paraphrases are instructional summaries of real primary sources, not quotations. This shortened mini-DBQ is NOT the official seven-document DBQ and uses an adapted six-point rubric.\n\nDocument 1 — Articles of Confederation, effective 1781: States retain powers not expressly delegated, while national expenses depend on state contributions. Source: ${sourceUrls.articles}\n\nDocument 2 — U.S. Constitution, 1787: Congress receives powers to tax and regulate interstate commerce, and federal institutions gain means to implement national law. Source: ${sourceUrls.constitution}\n\nDocument 3 — Indian Removal Act, 1830: Congress authorizes arrangements for land exchanges and movement of Indigenous nations westward under federal direction. This legal framing must be distinguished from subsequent coercive implementation. Primary-document collection and act materials: ${sourceUrls.removal}\n\nDocument 4 — Lincoln's Emancipation Proclamation, 1863: Using wartime authority, the president declares freedom in designated rebellious areas and authorizes the military acceptance of Black men. Source: ${sourceUrls.emancipation}`,miniCriteria('Examples of outside evidence include the Bank War, Worcester v. Georgia, the Fugitive Slave Act, or the Thirteenth Amendment. A strong qualification can contrast federal support for dispossession with wartime emancipation.'),
`Do not reward a description of removal as voluntary merely because a statute used negotiation language. Explain how institutions and authority changed, and assess the different effects of federal power without assuming a straight line toward equality.`);
function miniCriteria(outside:string){return[
criterion('thesis','Thesis',1,'Make a defensible claim answering the prompt.','Award 1 for a clear position and line of reasoning; merely repeating the prompt earns 0.'),
criterion('context','Context',1,'Explain broader developments relevant to the documents.','Award 1 for a developed connection to a relevant broader setting; a bare label or date earns 0.'),
criterion('documents','Document evidence',2,'Use the documents to support an argument.','Award up to 2: 1 for accurately describing relevant content from at least TWO documents; 2 for using content from at least THREE documents to support a defensible argument. Do not require direct quotations, and do not reward invented document claims.'),
criterion('sourcing','Sourcing analysis',1,'Explain why a source’s purpose, audience, situation, or viewpoint matters.','Award 1 for explaining how one sourcing feature affects interpretation of at least ONE document. Merely naming the author, repeating its date, or saying biased is insufficient.'),
criterion('outside','Outside evidence',1,'Use one distinct piece of evidence beyond the provided summaries.','Award 1 for a specific accurate outside example used to support the argument. Do not double-count a detail merely repeated from a provided document. '+outside)];}
written(6,2,1,'short_answer','SAQ: Comparing Interpretations of Industrialization',
`Sources: TWO original instructional secondary interpretations written by AscendSAT, not attributed quotations from published historians.\nInterpretation A: Industrial networks increased production and connected consumers to a wider variety of goods, making changes in economic scale central to the period.\nInterpretation B: Industrial growth concentrated bargaining power, exposing workers and farmers to decisions made by large corporations and financiers.\n\nA. Describe ONE difference in emphasis between the interpretations.\nB. Explain ONE specific development between 1865 and 1898 that supports A.\nC. Explain ONE specific development between 1865 and 1898 that supports B.`,[
criterion('A','Part A',1,'Describe a difference in emphasis.','Award 1 for distinguishing production/consumer access from the distribution of economic power or vulnerability. Claiming A says everyone benefited is inaccurate; the interpretation makes no such claim.'),
criterion('B','Part B',1,'Explain evidence supporting A.','Award 1 for connecting specific evidence such as railroad expansion, integrated national markets, or mass steel production to increased scale, output, or consumer access. A name alone is insufficient.'),
criterion('C','Part C',1,'Explain evidence supporting B.','Award 1 for connecting evidence such as Homestead, Pullman, railroad rate disputes, or farm indebtedness to unequal bargaining power. Do not accept a twentieth-century example unless it is explicitly used only for context and the supporting example is within the period.')],
`The interpretations are not mutually exclusive. A strong response can show that higher production and concentrated power occurred together, while keeping each requested supporting example distinct.`);
written(8,2,2,'short_answer','SAQ: A Civil Rights Statute in Context',
`Source: Congress, Civil Rights Act of 1964. Instructional paraphrase, not a quotation: The law prohibits specified forms of discrimination in public accommodations, federally assisted programs, and employment, and establishes enforcement mechanisms. Primary source: ${sourceUrls.civilRights}\n\nA. Identify ONE form of inequality addressed by the law.\nB. Explain ONE movement activity before 1964 that contributed to pressure for federal action.\nC. Explain ONE reason the law did not end all racial inequality by 1980.`,[
criterion('A','Part A',1,'Identify an inequality the law addressed.','Award 1 for an accurate example such as exclusion from covered public accommodations, racial employment discrimination, or discrimination in federally assisted programs. Do not require mastery of statutory section numbers.'),
criterion('B','Part B',1,'Explain movement pressure.','Award 1 for a specific example such as sit-ins, the Birmingham campaign, Freedom Rides, or the March on Washington connected to public pressure or federal responsibility. Listing an event without explaining influence earns 0.'),
criterion('C','Part C',1,'Explain a continuing source of inequality.','Award 1 for explaining how housing discrimination, unequal resources, enforcement resistance, or other accurate conditions sustained inequality. An answer claiming the law legalized segregation or eliminated all enforcement needs earns 0 for that claim.')],
`An effective answer gives activists a causal role and distinguishes legal prohibitions from their enforcement and from inequalities that a single statute did not fully address.`);
written(8,2,3,'long_essay','LEQ: Government and Economic Security',
`Industrialization, depression, war, and postwar growth changed Americans' expectations of economic security. Develop an argument evaluating changes in the federal government's role in promoting economic security between 1865 and 1980. You may focus on ONE or more developments rather than the entire period. Describe relevant context, support your position with at least TWO specific pieces of evidence, and explain a significant limitation, continuity, or competing interpretation. This broad original prompt practices the May 2027 direction of choice within a required question. The app's six-point criteria are instructional, not official.`,leqCriteria('Relevant evidence might include railroad support, labor injunctions, Social Security, the Wagner Act, the GI Bill, Medicare, or antipoverty programs. Explain whom policies served or excluded. Other defensible evidence is acceptable.'),
`One defensible argument traces a shift from protecting property and transport toward expanded social insurance and labor protections, while acknowledging continuing business support and unequal access. A different periodization is acceptable if supported.`);
written(8,2,4,'mini_dbq','Mini-DBQ: Federal Institutions and Equal Citizenship',
`Evaluate how federal institutions both advanced and limited equal citizenship between 1868 and 1964. Use the FOUR document summaries and at least ONE specific outside example. All summaries below are instructional paraphrases of identified real primary sources, not quotations. This is a shortened six-point practice task, NOT a full official seven-document DBQ.\n\nDocument 1 — Fourteenth Amendment, ratified 1868: National citizenship, due process, and equal protection impose constitutional limits on state action. Source: ${sourceUrls.amendment14}\n\nDocument 2 — Plessy v. Ferguson, majority ruling, 1896: The Court upholds state-required racial separation in railroad accommodations under a distinction between legal equality and social separation. This summarizes the majority's reasoning, not an endorsement of its claims. Source: ${sourceUrls.plessy}\n\nDocument 3 — Executive Order 9066, 1942: The president authorizes military exclusion zones and removal of persons from them. The order did not name Japanese Americans in its text; implementation led to their mass forced removal and incarceration. Source: ${sourceUrls.eo9066}\n\nDocument 4 — Civil Rights Act, 1964: Congress prohibits major forms of discrimination and strengthens federal enforcement in covered settings. Source: ${sourceUrls.civilRights}`,miniCriteria('Outside evidence might include Reconstruction enforcement, the Civil Rights Cases, Brown, Black movement organizing, or resistance to incarceration. Do not substitute events after 1964 for the requested argument.'),
`A developed argument can contrast constitutional protection and civil-rights legislation with judicial sanction for segregation and executive wartime coercion. Institutions and outcomes changed over time; federal power was neither uniformly protective nor uniformly restrictive.`);
export const references=[
{title:'AP U.S. History — Course Framework',url:'https://apcentral.collegeboard.org/courses/ap-united-states-history',description:'Official nine-period framework and historical thinking skills; reviewed November 7, 2026.'},
{title:'AP U.S. History — Exam',url:'https://apcentral.collegeboard.org/courses/ap-united-states-history/exam',description:'Official current exam structure, including May 2027 source-based SAQ and broad LEQ directions.'},
{title:'AP History Exam Updates — May 2027',url:'https://apcentral.collegeboard.org/courses/ap-history-exam-updates',description:'Official summary: all three SAQs required and source-based; one broad required LEQ; DBQ remains seven documents.'},
{title:'AP U.S. History CED — Effective Fall 2026',url:'https://apcentral.collegeboard.org/media/pdf/ap-us-history-course-and-exam-description.pdf',description:'Official framework reference; no released questions reproduced in this content.'},
...Object.entries(sourceUrls).map(([title,url])=>({title:`Primary source — ${title}`,url,description:'Government archive or primary-document collection supporting identified paraphrases in original practice.'}))
];
export const lessons=chapters.map((c,i)=>({id:`apush-lesson-${c.unit}-${c.number}`,title:`${c.unit}.${c.number} ${c.title}`,domain:domain(c.unit),difficulty:'Medium',videoUrl:'',content:[{type:'heading',text:`${c.unit}.${c.number} ${c.title}`},{type:'text',text:c.explanation},{type:'heading',text:'Worked historical reasoning'},{type:'text',text:c.worked},{type:'heading',text:'Common errors to avoid'},{type:'text',text:c.error},{type:'heading',text:'Check your understanding'},{type:'text',text:c.check}],practiceQuestions:mcq.filter(q=>q.lessonTitle===`${c.unit}.${c.number} ${c.title}`).map(({id,question,choices,answer,explanation})=>({id,question,choices,answer,explanation}))}));
export const flashcards=chapters.flatMap(c=>c.terms.map(([term,answer]:[string,string],i:number)=>({id:`apush-card-${c.unit}-${c.number}-${i+1}`,unit:domain(c.unit),term,answer})));
export const APUSH_CONTENT={lessons,mcq,frq,flashcards,references};
